var e=JSON.parse(`[{"SettingName":"Marriage_SpouseGenders","Description":"Allowable genders for the spouse sim to be. When Marriage_SameSexPercentage is greater than zero, this is used to determine valid genders. Values are 'M,F'.","MenuPath":"MCCC > MC Pregnancy > Spouse Sim Selection > Spouse Gender","DefaultValue":"'M'","Module":"MC Marriage"},{"SettingName":"Marriage_RenameSameGender","Description":"Normally, when Sims are married, females last name are changed when married to a male. If Marriage_SpouseGenders includes 'F', this will also rename the Sim/household for a female/female marriage. The last name will be changed to the inseminating Sim. Values are true/false.","MenuPath":"MCCC > MC Pregnancy > Other Marriage > Rename Same Gender","DefaultValue":"false","Module":"MC Marriage"},{"SettingName":"Marriage_MoveFamilies","Description":"Keep children with their parent Sim when that Sim moves, even if other adult Sims are in the household. Values are true/false.","MenuPath":"MCCC > MC Pregnancy > Other Marriage > Move Families","DefaultValue":"true","Module":"MC Marriage"},{"SettingName":"Marriage_BypassPlayedHouseholds","Description":"Bypasses any household flagged as a 'Played Household' in the Manage Households screen so it will not be used for marriages. If this is false, only the active household will be bypassed.","MenuPath":"MCCC > MC Pregnancy > Marriage Sim Selection > Bypass Played Households","DefaultValue":"true","Module":"MC Marriage"},{"SettingName":"Marriage_BypassActiveRomanticInterest","Description":"If this is true then if an active Sim is in a serious relationship with another Sim, they will not get married with someone else. If this is false, there's a chance that any non-active Sim may suddenly get married to a random Sim and forget about any engagement with someone in the active household.","MenuPath":"MCCC > MC Pregnancy > Marriage Sim Selection > Bypass active Sim romances","DefaultValue":"true","Module":"MC Marriage"},{"SettingName":"Marriage_OccupancyType","Description":"If it is '', the default value, any Sims may be used for partners for marriage. If it is 'HL'-Homeless Only, then only homeless Sims will be used as partners for Marriage. If there are no valid Homeless Sims available, then no marriages will happen. If it is 'PH'-Prefer Home Sims, then marriage partners will first come from valid homed Sims and then from valid homeless Sims if necessary. If it is 'HO'-Living in Homes Only, then only valid Sims living in homes will be used as partners for marriage.","MenuPath":"MCCC > MC Pregnancy > Spouse Sim Selection > Occupancy Preference","DefaultValue":"''","Module":"MC Marriage"},{"SettingName":"Marriage_DaysToRun","Description":"This setting allows overriding the default days that marriage random checks run. The settings include 'SU', 'MO', 'TU', 'WE', 'TH', 'FR', 'SA'. If it is left blank, it will use the defaults built into MC Command Center based on the aging speed.","MenuPath":"MCCC > MC Pregnancy > Marriage Sim Selection > Days to Run Checks","DefaultValue":"Blank","Module":"MC Marriage"},{"SettingName":"Marriage_UseSameAgeGroup","Description":"When choosing a spouse for a random marriage, Sims are coupled based on being the same age in addition to other criteria.","MenuPath":"MCCC > MC Pregnancy > Spouse Sim Selection > Use Same Age Group","DefaultValue":"False","Module":"MC Marriage"},{"SettingName":"Marriage_AllowHomeless","Description":"When enabled, homeless Sims are eligible as targets for random marriages. This is specifically used for determining valid targets. Marriage_OccupancyType is used to determine what living conditions are required for spouses. A Sim living on a lot will never move into a homeless household as a result of marriage. So, if we're doing a random marriage check for a homeless Sim, only another homeless Sim can be their partner. If we're doing a random check on a Sim on a lot, another Sim on a lot or a homeless Sim is valid for their spouse.","MenuPath":"MCCC > MC Pregnancy > Marriage Sim Selection > Allow Homeless Marriage","DefaultValue":"False","Module":"MC Marriage"},{"SettingName":"Marriage_RenameOppositeSex","Description":"Determines which gender is used for the 'Last Name' of an opposite-sex married couple when MC Pregnancy marries two Sims. It can be 'N' if no renaming is desired, 'M' for the Male's name to always be used, 'F' for the Female's name to always be used, 'R' if a random choice of the Male or Female is desired or 'RN' to randomly use Male, Female or No last name changes.","MenuPath":"MCCC > MC Pregnancy > Other Marriage > Rename Opposite Sex","DefaultValue":"M","Module":"MC Marriage"},{"SettingName":"Marriage_UseTraitsForMarriage","Description":"If this setting is enabled, then the percentage chance that an NPC Sim will get married will be raised or lowered based on traits they have. Non-committal and Loner = penalty. Family Oriented and Romantic = Bonus.","MenuPath":"MCCC > MC Pregnancy > Other Marriage > Use Traits For Marriage","DefaultValue":"False","Module":"MC Marriage"},{"SettingName":"Show_MarriageNotificationType","Description":"Will display a notification post when a Sim gets married depending on whether the Sim falls within the limits of this setting. These include: '0'-No marriage notifications, 'N'-NPC's only, 'P'-Played/Active Sims only, 'R'-Sims related to the Active Sims only, 'AF'-Sims that are friends of the Active Sims only, 'AR'-Sims that are romantically involved with the Active Sims only or 'AL'-All Sims not in the active household will show marriage notifications.","MenuPath":"MCCC Settings > Notification/Console/Menu Settings > Notification Settings > MC Pregnancy Notifications > Show Marriage Notifications","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Marriage_RemoveServiceRoleLimit","Description":"When enabled, the limit EA added recently so active Sims cannot marry Sims in service roles to them will be removed. This will basically make marriage with service Sims work like it did prior to EA's changes in the Toddler update.","MenuPath":"MCCC > MC Pregnancy > Other Marriage > Remove Service Limit","DefaultValue":"False","Module":"MC Marriage"},{"SettingName":"Marriage_ManualRenameSpouses","Description":"This option displays a dialog allowing either last name of married Sims to be selected. Depending on the rules defined for Marriage_RenameOppositeSex and Marriage_RenameSameGender, an option to randomly choose one of the two available last names or to make no changes to the last name may also be available. Setting this to 'Included Played Household' will show the dialog if either Sim getting married is a played Sim. Setting it to 'All' will display the dialog if the Sims getting married are played or NPC Sims. Note that this does nothing for active Sim households. Special considerations: 1) Unique Sims generated by EA will not work on this process. As their names are defined by keys within the system and are not 'text', I cannot use the names in any functions. 2) Active Sims are not married through my automated process. They are married through EA's situations so I don't have control over them. 3) Clicking the 'X' on the rename dialog or hitting Escape will result in NO RENAME happening for the couple at all. This is the way dialogs and their timing works within the game engine…nothing I can do about that! 4) Ancestral Homes always control the naming of married Sims so will not show dialogs.","MenuPath":"MCCC > MC Pregnancy->Other Marriage->Manually Rename Spouses","DefaultValue":"'A'","Module":"MC Marriage"},{"SettingName":"Woohoo_AllowFamily","Description":"Allow romantic interactions between related Sims","MenuPath":"MCCC > MC Woohoo > Woohoo Actions > Allow Family","DefaultValue":"false","Module":"MC Woohoo"},{"SettingName":"Woohoo_AllowTeens","Description":"Allow romantic interactions between adults and teens, including Try for baby.","MenuPath":"MCCC > MC Woohoo > Woohoo Actions > Allow Teens","DefaultValue":"false","Module":"MC Woohoo"},{"SettingName":"Woohoo_BedSharing","Description":"Allow any Sims to sleep in the same bed.","MenuPath":"MCCC > MC Woohoo > Woohoo Reactions > Bed Sharing","DefaultValue":"false","Module":"MC Woohoo"},{"SettingName":"Woohoo_BirthControlDuration","Description":"Allows changing the duration that the Birth Control buff lasts from 1 through 24 hours.","MenuPath":"MCCC > MC Woohoo > Other Settings > Birth Control Duration","DefaultValue":"2 hours","Module":"MC Woohoo"},{"SettingName":"Woohoo_BirthControlAllMoods","Description":"If enabled, the 'Birth Control' interaction shows-up regardless of the mood. If disabled, the Sim must be in a Flirty mood for the interaction to be visible.","MenuPath":"MCCC > MC Woohoo > Other Settings > All Moods Birth Control","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Woohoo_DisableJealousy","Description":"Romantic relationships do not trigger jealousy in other Sims. Note that if a Sim has the 'Jealousy' trait or if a club situation is having where jealousy is encouraged, it can override this setting.","MenuPath":"MCCC > MC Woohoo > Woohoo Reactions > No Jealousy","DefaultValue":"false","Module":"MC Woohoo"},{"SettingName":"Woohoo_UseFertileInRisky","Description":"If this is true, then when calculating the chance that a Sim will get pregnant with Risky Woohoo, if they have the Fertile trait, they are even more likely to get pregnant. If Risky Woohoo Percent is zero, this setting will have no effect.","MenuPath":"MCCC > MC Woohoo > Woohoo Pregnancy > Use Fertility in Risky","DefaultValue":"false","Module":"MC Woohoo"},{"SettingName":"Woohoo_SameSexTryForBaby","Description":"Try for Baby options are available between two Sims of the same gender.","MenuPath":"MCCC > MC Woohoo > Woohoo Actions > Same Sex Try For Baby","DefaultValue":"false","Module":"MC Woohoo"},{"SettingName":"Woohoo_UsePrivacy","Description":"If this is enabled, Sims shoo other Sims from the room when they woohoo. If disabled, they do not.","MenuPath":"MCCC > MC Woohoo > Woohoo Reactions > Use Privacy for Woohoo","DefaultValue":"true","Module":"MC Woohoo"},{"SettingName":"Woohoo_AutonomousWoohoo","Description":"If this is enabled, Sims may autonomously use the Woohoo interactions","MenuPath":"MCCC > MC Woohoo > Other Settings > Autonomous Woohoo","DefaultValue":"true","Module":"MC Woohoo"},{"SettingName":"Woohoo_AutonomousTryForBaby","Description":"If this is enabled, Sims may autonomously use the Try for Baby interactions","MenuPath":"MCCC > MC Woohoo > Other Settings > Autonomous Try For Baby","DefaultValue":"false","Module":"MC Woohoo"},{"SettingName":"Woohoo_SameSexPregnantSim","Description":"Determines whether the Target of the 'Try for Baby' interaction, the Initiator of the interaction, or possibly both Sims in the interaction will become pregnant.","MenuPath":"MCCC > MC Woohoo > Woohoo Pregnancy > Same Sex Pregnancy Sim","DefaultValue":"'T'","Module":"MC Woohoo"},{"SettingName":"Woohoo_OppositeSexPregnantSim","Description":"When Male/Female 'Try for Baby' or Risky Woohoo interactions happens, determines whether the female, male, Target, Initiator, or some combination of those choices will become pregnant from the interaction. I really recommend either using 'male' and 'female' or 'Initiator' and 'Target' be used. But, if you want to use a combination, the code is there to support it. Just be prepared to possibly think several levels deep to understand who became pregnant in different situations.","MenuPath":"MCCC > MC Woohoo > Woohoo Pregnancy > Opposite Sex Pregnancy Sim","DefaultValue":"'F'","Module":"MC Woohoo"},{"SettingName":"Woohoo_NudeWoohooGender","Description":"The gender of Sim that will have Nude Woohoo. 'F'-Female and 'M'-Male are valid options. Both may be selected with 'F,M'. Blank means neither.","MenuPath":"MCCC > MC Woohoo > Sim Nudity > Nudity Genders","DefaultValue":"Blank","Module":"MC Woohoo"},{"SettingName":"Woohoo_NudityAges","Description":"Ages that are valid for Nude Woohoo. Valid ages are 'T', 'YA', 'A' and 'E'. If none are defined, no Sims will become nude for Woohoo of any type.","MenuPath":"MCCC > MC Woohoo > Sim Nudity > Nudity Ages","DefaultValue":"'YA,A'","Module":"MC Woohoo"},{"SettingName":"Woohoo_NudeWoohoo","Description":"Determines whether Sims defined in Woohoo_NudeWoohooGender and Woohoo_NudityAges will become nude for bed woohoo.","MenuPath":"MCCC > MC Woohoo > Sim Nudity > Nudity Interactions > Nude Woohoo","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Woohoo_NudeInHotTub","Description":"Determines whether Sims defined in Woohoo_NudeWoohooGender and Woohoo_NudityAges will become nude for Hot Tub woohoo.","MenuPath":"MCCC > MC Woohoo > Sim Nudity > Nudity Interactions > Nude Hot Tub Woohoo","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Woohoo_NudeInSauna","Description":"Determines whether Sims defined in Woohoo_NudeWoohooGender and Woohoo_NudityAges will become nude for Sauna woohoo.","MenuPath":"MCCC > MC Woohoo > Sim Nudity > Nudity Interactions > Nude Sauna Woohoo","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Woohoo_NudeSpa","Description":"Determines whether Sims defined in Woohoo_NudeWoohooGender and Woohoo_NudityAges will become nude when receiving Massages or taking mudbaths.","MenuPath":"MCCC > MC Woohoo > Sim Nudity > Nudity Interactions > Nude Spa","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Woohoo_NudeWorkout","Description":"Determines whether Sims defined in Woohoo_NudeWoohooGender and Woohoo_NudityAges will become nude when working out on gym equipment.","MenuPath":"MCCC > MC Woohoo > Sim Nudity > Nudity Interactions > Nude Workout","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Woohoo_NudeYoga","Description":"Determines whether Sims defined in Woohoo_NudeWoohooGender and Woohoo_NudityAges will become nude when doing Yoga.","MenuPath":"MCCC > MC Woohoo > Sim Nudity > Nudity Interactions > Nude Yoga","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Woohoo_RemainNude","Description":"Determines whether Sims will stay nude after Bed Woohoo or will change into their sleeping clothes. This only applies to Bed woohoo. All other woohoos change clothes automatically.","MenuPath":"MCCC > MC Woohoo > Sim Nudity > Stay Nude after Woohoo","DefaultValue":"True","Module":"MC Woohoo"},{"SettingName":"Woohoo_ElderTryForBaby","Description":"If enabled, Try for Baby interactions will be available for male and female elder Sims.","MenuPath":"MCCC > MC Woohoo > Woohoo Actions > Elder Try For Baby","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Woohoo_TryForBabyPercent","Description":"The percentage chance that Try for Baby interactions will result in pregnancy.","MenuPath":"MCCC > MC Woohoo > Woohoo Pregnancy > Try For Baby Percent","DefaultValue":"80","Module":"MC Woohoo"},{"SettingName":"Woohoo_UseWoohooSkill","Description":"Use the optional Woohoo Skill included with MC Woohoo.","MenuPath":"MCCC > MC Woohoo > Other Settings > Use Woohoo Skill","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Woohoo_AutonomousMinRestTime","Description":"The number of minimum hours Sims will wait before trying to do autonomous woohoo/try for baby again. Valid values are from 0 to 24 hours.","MenuPath":"MCCC > MC Woohoo > Other Settings > Autonomous Rest Time","DefaultValue":"6","Module":"MC Woohoo"},{"SettingName":"Woohoo_SleepyWoohoo","Description":"If true, then if a visiting Sim has bed Woohoo between the hours of 10PM and 4AM, the Sim will go to sleep afterwards.","MenuPath":"MCCC > MC Woohoo > Woohoo Reactions > Sleepy Woohoo","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Woohoo_AllowTFB","Description":"If disabled, then the 'Try For Baby' interactions will be removed from all menus. As a result, pregnancy will only be able to be achieved by active Sims by using Risky Woohoo options.","MenuPath":"MCCC > MC Woohoo > Woohoo Actions > Allow Try for Baby","DefaultValue":"True","Module":"MC Woohoo"},{"SettingName":"Woohoo_ExtremeWoohoo","Description":"With this setting, Woohoo will happen a lot more often autonomously. I recommend using the 'Autonomous Rest Time' setting to give breaks between autonomous Woohoo. Note that this setting requires either Autonomous Woohoo or Autonomous Try for Baby to be enabled. Otherwise, it won't do anything. Also note that with this setting disabled, autonomous Woohoo will happen based solely on EA's prioritization with no tweaks from my mod.","MenuPath":"MCCC > MC Woohoo > Other Settings > Extreme Woohoo","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Tuner_AutoMarriage","Description":"Allow marriages to happen autonomously","MenuPath":"MCCC > MC Tuner > Change Interaction Autonomy > Autonomous Marriage","DefaultValue":"false","Module":"MC Tuner"},{"SettingName":"Tuner_AutoProposal","Description":"Allow proposals, ask to be boyfriend/girlfriend and promise ring exchange to happen autonomously","MenuPath":"MCCC > MC Tuner > Change Interaction Autonomy > Autonomous Proposals","DefaultValue":"false","Module":"MC Tuner"},{"SettingName":"Tuner_AutoMean","Description":"Allow mean interactions to happen autonomously","MenuPath":"MCCC > MC Tuner > Change Interaction Autonomy > Autonomous Mean","DefaultValue":"true","Module":"MC Tuner"},{"SettingName":"Tuner_AutoMischief","Description":"Allow mischief interactions to happen autonomously","MenuPath":"MCCC > MC Tuner > Change Interaction Autonomy > Autonomous Mischief","DefaultValue":"true","Module":"MC Tuner"},{"SettingName":"Tuner_AutoFlirty","Description":"Disabling this setting will turn-off autonomous Flirty and Romantic interactions for Sims.","MenuPath":"MCCC > MC Tuner > Change Interaction Autonomy > Autonomous Flirty","DefaultValue":"true","Module":"MC Tuner"},{"SettingName":"Tuner_FriendlyAskSingle","Description":"Changes 'Ask If Single' interaction to be friendly instead of romantic","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior > Friendly Ask If Single","DefaultValue":"false","Module":"MC Tuner"},{"SettingName":"Tuner_FriendlyStayNight","Description":"Changes 'Invite to Stay the Night' interaction to be friendly instead of romantic","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior > Friendly Stay The Night","DefaultValue":"false","Module":"MC Tuner"},{"SettingName":"Tuner_KissesAlwaysAvailable","Description":"When enabled, Passionate and Suave kisses are always available regardless of mood or time-outs.","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior > Kisses Always Available","DefaultValue":"false","Module":"MC Tuner"},{"SettingName":"Tuner_AllowMoodDeath","Description":"If disabled, it turns-off any death that is a result of an emotion getting too extreme (Playful, Angry or embarrassed).","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior > Allow Emotional Deaths","DefaultValue":"true","Module":"MC Tuner"},{"SettingName":"Tuner_AutoRepair","Description":"If enabled, any Sim Teen-or-older on a lot may repair something that is broken autonomously.","MenuPath":"MCCC > MC Tuner > Change Interaction Autonomy > Autonomous Repairs","DefaultValue":"false","Module":"MC Tuner"},{"SettingName":"Tuner_AutoClean","Description":"If enabled, any Sim Teen-or-older on a lot may repair something that is dirty autonomously.","MenuPath":"MCCC > MC Tuner > Change Interaction Autonomy > Autonomous Cleaning","DefaultValue":"false","Module":"MC Tuner"},{"SettingName":"Tuner_StopRandomFlirting","Description":"If enabled, this setting will prevent random flirting between Sims when they are in a flirty mood. There must be some romantic relationship levels between the two Sims for the flirting to happen autonomously. If this setting is enabled, it overrides the 'Autonomous Flirty' setting as they are conflicting and this setting takes priority when both settings are in use. This setting will not necessarily prevent flirting from happening when a Sim is under a vampire charm or if a club situation is in-progress that encourages flirting. Those situations are special and override the standard autonomy rules for flirting behavior. Be aware that this may also prevent autonomous Woohoo from happening outside of romantic situations even if 'No Strings' woohoo is enabled.","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior > Stop Random Flirting","DefaultValue":"false","Module":"MC Tuner"},{"SettingName":"Tuner_AllowMonsterUnderBed","Description":"If this is disabled, it has a two-part effect. 1) No more monsters under the bed. 2) Toddlers don't have nightmares any more.","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior > Allow Monster Under Bed","DefaultValue":"true","Module":"MC Tuner"},{"SettingName":"Pregnancy_AutoMarryPercent","Description":"A percentage determining whether or not to marry and move-in Sims after pregnancy is triggered. 0% will never happen, 100% will always happen.","MenuPath":"MCCC > MC Pregnancy > Other Pregnancy > Auto-Marry Percentage","DefaultValue":"0","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_InsiminateGenders","Description":"Allowable genders for the insiminating sim to be. When Pregnancy_SameSexPercentage fails to be met during a pregnancy, this is used to determine valid genders. Values are 'M,F'.","MenuPath":"MCCC > MC Pregnancy > Partner Sim Selection > Partner Gender","DefaultValue":"'M'","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_OffspringGender","Description":"Allowable genders for babies. Values are 'M' - Male and 'F' - Female.","MenuPath":"MCCC > MC Pregnancy > Offspring > Offspring Gender","DefaultValue":"'M,F'","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_MaxOffspring","Description":"Maximum allowable offspring. This just limits the number of babies to not be greater than the specified number. If one is specified, no twins or triplets will be born. The maximum value for this setting is 6. The higher the number, the greater the odds to have multiple offspring at delivery.","MenuPath":"MCCC > MC Pregnancy > Offspring > Maximum Offspring","DefaultValue":"3","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_EnforceFamily","Description":"Don't allow a Sim to be impregnated by another Sim if they are related. Note that this setting will only be available if the MC Woohoo module is deployed.","MenuPath":"MCCC > MC Pregnancy > Partner Sim Selection > Enforce Family","DefaultValue":"True","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_MaxHouseholdChildren","Description":"This number determines the maximum number of children that a household will reach through pregnancies. It is basically a total counter of the number of children a parent can have throughout their life. Values are from 1 to 50.","MenuPath":"MCCC > MC Pregnancy > Offspring > Maximum Household Children","DefaultValue":"3","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_BypassPlayedHouseholds","Description":"Bypasses any household flagged as a 'Played Household' in the Manage Households screen so it will not be used for pregnancy. If this is false, only the active household will be bypassed.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Bypass Played Households","DefaultValue":"true","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_BypassActiveRomanticInterest","Description":"If this is true then if an active Sim is in a serious relationship with another Sim, they will not get pregnant with someone else.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Bypass active Sim romances","DefaultValue":"true","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_OccupancyType","Description":"If it is '', the default value, any Sims may be used for partners for pregnancy. If it is 'HL'-Homeless Only, then only homeless Sims will be used as partners for Pregnancy. If there are no valid Homeless Sims available, then no pregnancies will happen. If it is 'PH'-Prefer Home Sims, then pregnancy partners will first come from valid homed Sims and then from valid homeless Sims if necessary. If it is 'HO'-Living in Homes Only, then only valid Sims living in homes will be used as partners for pregnancy.","MenuPath":"MCCC > MC Pregnancy > Partner Sim Selection > Occupancy Preference","DefaultValue":"''","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_DaysToRun","Description":"This setting allows overriding the default days that pregnancy random checks run. The settings include 'SU', 'MO', 'TU', 'WE', 'TH', 'FR', 'SA'. If it is left blank, it will use the defaults built into MC Command Center based on the aging speed.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Days to Run Checks","DefaultValue":"Blank","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_PauseOnPlayableLabor","Description":"If this is enabled, when an inactive played household has a Sim go into labor, a dialog will notify the player allowing opportunity to switch to the other household to deliver the baby.","MenuPath":"MCCC > MC Pregnancy > Other Pregnancy > Pause on Playable Labor","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_UseSameAgeGroup","Description":"When choosing a partner for a random pregnancy, Sims are coupled based on being the same age in addition to other criteria.","MenuPath":"MCCC > MC Pregnancy > Partner Sim Selection > Use Same Age Group","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_AgeWhenPregnant","Description":"When Sims are pregnant, they don't stop aging, which happens using the EA coding. The default will make it work as it does currently. Note, that this allows the Sim age to continue through the span of days in their age. It does NOT allow them to transition from one age-span to another.","MenuPath":"MCCC > MC Pregnancy > Other Pregnancy > Allow Pregnancy Aging","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_AllowHomeless","Description":"When enabled, homeless Sims are eligible as targets for random pregnancies. This is specifically used for determining valid targets. Pregnancy_OccupancyType is used to determine what living conditions are required for partners. A Sim living on a lot will never move into a homeless household as a result of pregnancies. So, if we're doing a random pregnancy check for a homeless Sim, only another homeless Sim can be their partner. If we're doing a random check on a Sim on a lot, another Sim on a lot or a homeless Sim is valid for their partner.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Allow Homeless Pregnancy","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_Duration","Description":"Determines the number of days a pregnant Sim will be carrying their baby before delivery. A value between 1 and 120 days is allowed. Note that if a longer duration is chosen for pregnancy than the life span of a Sim and they are an elder and the Pregnancy_AgeWhenPregnant setting is true, then a Sim could die before delivering their baby.","MenuPath":"MCCC > MC Pregnancy > Other Pregnancy > Pregnancy Duration","DefaultValue":"3","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_SameSexAdoptionPercent","Description":"Defines a percentage chance that same-sex couples will adopt a child rather than having a same-sex pregnancy. If it is set to 100, then only adoption will be used for same-sex couples. If it is zero, then only pregnancies will be used for same-sex couples. Like all adoptions, children adopted in this manner will not have any of the parent genetics and there will be one child only.","MenuPath":"MCCC > MC Pregnancy > Adoption Settings > Same Sex Adoption Percent","DefaultValue":"0","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_AdoptionAges","Description":"Works with the Pregnancy_SameSexAdoptionPercent setting. If a random adoption is determined to happen, the age of the child adopted will be based on this setting. Valid values are 'B'-Baby, 'TD'-Toddler, 'C'-Child, 'T'-Teen. The age is randomly selected from whatever values are specified in this setting.","MenuPath":"MCCC > MC Pregnancy > Adoption Settings > Adoption Ages","DefaultValue":"B,TD,C,T","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_UseTraitsForPregnancy","Description":"If this setting is enabled, then the percentage chance that an NPC Sim will become pregnant will be raised or lowered based on traits they have. Hate Children = penalty. Family Oriented = Bonus.","MenuPath":"MCCC > MC Pregnancy > Other Pregnancy > Use Traits For Pregnancy","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Show_BirthNotificationType","Description":"Will display a notification post when a Sim delivers babies depending on whether the Sim falls within the limits of this setting. These include: '0'-No birth notifications, 'N'-NPC's only, 'P'-Played/Active Sims only, 'R'-Sims related to the Active Sims only, 'AF'-Sims that are friends of the Active Sims only, 'AR'-Sims that are romantically involved with the Active Sims only or 'AL'-All Sims not in the active household will show notifications on delivery.","MenuPath":"MCCC Settings > Notification/Console/Menu Settings > Notification Settings > MC Pregnancy Notifications > Show Birth Notifications","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Show_BirthNotificationDetails","Description":"If this is true, the names of all babies delivered will be displayed in addition to the summary details for total babies delivered. If it is false, then only the summary data will be displayed.","MenuPath":"MCCC Settings > Notification/Console/Menu Settings > Notification Settings > MC Pregnancy Notifications > Show Birth Notification Details","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Show_PregnancyNotificationType","Description":"Will display a notification post when a Sim gets pregnant depending on whether the Sim falls within the limits of this setting. These include: '0'-No pregnancy notifications, 'N'-NPC's only, 'P'-Played/Active Sims only, 'R'-Sims related to the Active Sims only, 'AF'-Sims that are friends of the Active Sims only, 'AR'-Sims that are romantically involved with the Active Sims only or 'AL'-All Sims not in the active household will show pregnancy notifications.","MenuPath":"MCCC Settings > Notification/Console/Menu Settings > Notification Settings > MC Pregnancy Notifications > Show Pregnancy Notifications","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Pregnancy_NameInactiveOffspring","Description":"Setting this to 'Included Played Households' will display the baby naming dialog for any babies born to a played Sim in addition to the active household. Setting it to 'Related to Active Household' will show the baby naming dialog for any babies born to Sims related to an active Sim or if the baby itself is the offspring of an NPC and an active Sim. Setting it to 'All' will display the baby-naming dialog for any Sim delivery a baby in the world. 'Include Active Sims Only' is the default and the way naming of offspring works in the default game.","MenuPath":"MCCC > MC Pregnancy > Offspring > Rename Non-Active Offspring","DefaultValue":"'A'","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_NameInactiveAdoption","Description":"Setting this to 'Included Played Households' will display the adoption naming dialog for any children adopted to a played Sim through random pregnancy-adoption results. Setting it to 'Related to Active Household' will show the baby naming dialog for any children adopted by Sims related to an active Sim. Setting it to 'All' will display the adoption naming dialog for any Sim adopted in the world. Defaults to 'Include Active Sims Only' as that is the EA default.","MenuPath":"MCCC > MC Pregnancy->Adoption Settings->Rename Non-Active Adoptions","DefaultValue":"'A'","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_IdenticalOffspringChance","Description":"This percentage determines the likelihood that multiple offspring of the same gender will be 'identical' genetically. If left at the default value, it uses whatever EA specifies is the default, which is normally 33%.","MenuPath":"MCCC > MC Pregnancy > Offspring > Identical Sibling Chance","DefaultValue":"33","Module":"MC Pregnancy"},{"SettingName":"Population_OpenHouses","Description":"When moving homeless Sims into empty lots, how many lots in the world should we leave unoccupied. Setting this to a high number like 50 will prevent move-ins by homeless Sims. Additionally, individual lots can be edited and if the number of beds is set to zero in the Lot Info, then no Sims will move into the house.","MenuPath":"MCCC > MC Population > Moving Settings > Open Houses","DefaultValue":"1","Module":"MC Population"},{"SettingName":"Population_MaximumHomeless","Description":"Only generate homeless households up to this number. After that, don't generate anymore until the number drops below it. There will NEVER be zero homeless created. This number limits the homeless FAMILIES generated, not the homeless single-Sim households that are used by the core game for NPC careers and roles. Those are not touched by my code to ensure that the game doesn't break. If the number of homeless in the world (not including retirement homes) is less-than-or-equal-to this setting, then the homeless will not move into a house.","MenuPath":"MCCC > MC Population > Moving Settings > Maximum Homeless","DefaultValue":"-1 which is no limit","Module":"MC Population"},{"SettingName":"Population_RunDresser","Description":"If the McCmdCenter_dresser module is available for use, when creating new Sims from population module, run 'dresser_cleanup' after creating them.","MenuPath":"MCCC > MC Population > Populating Settings > Run Dresser","DefaultValue":"false","Module":"MC Population"},{"SettingName":"Population_PercentMale","Description":"The % chance a spawned homeless Sim will be male. Otherwise, it will be a female.","MenuPath":"MCCC > MC Population > Populating Settings > Percent Male","DefaultValue":"50","Module":"MC Population"},{"SettingName":"Population_PercentElder","Description":"The % chance a spawned homeless Sim will be an elder. Default age for adult Sim is Young Adult if elders and adults are not randomly selected.","MenuPath":"MCCC > MC Population > Populating Settings > Percent Elder","DefaultValue":"33","Module":"MC Population"},{"SettingName":"Population_PercentAdult","Description":"The % chance a spawned homeless Sim will be an adult. Default age for adult Sim is Young Adult if elders and adults are not randomly selected.","MenuPath":"MCCC > MC Population > Populating Settings > Percent Adult","DefaultValue":"33","Module":"MC Population"},{"SettingName":"Population_PercentChild","Description":"The % chance a spawned homeless dependent Sim will be a Child. Default age for dependents is Teen, which is used if infant, toddler, child or babies are not randomly selected.","MenuPath":"MCCC > MC Population > Populating Settings > Percent Child","DefaultValue":"20","Module":"MC Population"},{"SettingName":"Population_PercentBaby","Description":"The % chance a spawned homeless dependent Sim will be a baby. Default age for dependents is Teen, which is used if infant, toddler, child or babies are not randomly selected.","MenuPath":"MCCC > MC Population > Populating Settings > Percent Baby","DefaultValue":"20","Module":"MC Population"},{"SettingName":"Population_PercentToddler","Description":"The % chance a spawned homeless dependent Sim will be a toddler. Default age for dependents is Teen, which is used if infant, toddler, child or babies are not randomly selected.","MenuPath":"MCCC > MC Population > Populating Settings > Percent Toddler","DefaultValue":"20","Module":"MC Population"},{"SettingName":"Population_MoveOutEldersType","Description":"In non-active households, move-out elders if possible without leaving dependents alone in the house. We create a new household for the elders, a 'retirement' home, as it were. If it fills up before they pass on, others will be used for additional elders. Options include 'All' to move all elders to retirement homes, 'None' to move no elders and 'Non-Ancestral' to only move elders that are not in Ancestral Homes.","MenuPath":"MCCC > MC Population > Moving Settings > Move Out Elders","DefaultValue":"''","Module":"MC Population"},{"SettingName":"Population_MoveOutSingleSim","Description":"In non-active households on lots with houses, if a single adult lives in the household, move them into available lots with houses before moving homeless households.","MenuPath":"MCCC > MC Population > Moving Settings > Move single Sims","DefaultValue":"false","Module":"MC Population"},{"SettingName":"Population_RandomizeVisitingSims","Description":"Randomizes the Sims that show-up to different lots visited by the active Sim to try to provide more of a variety if True. This feature only takes the list of Sims that EA determines are valid for visiting and shuffles them so they're random rather than always spawning them in the same order every time, which is the default behavior. It in no way changes or influences who EA chooses as valid to visit the lot.","MenuPath":"MCCC > MC Population > Other Settings > Randomize Visiting Sims","DefaultValue":"False","Module":"MC Population"},{"SettingName":"Population_BypassCulling","Description":"If enabled, the EA Culling process that deletes Sims will be deactivated. No culling will occur (although ghost cleaning can still happen if enabled in MC Cleaner). After changing, the game must be restarted for the changes to take effect.","MenuPath":"MCCC > MC Population > Other Settings > Bypass Sim Culling","DefaultValue":"False","Module":"MC Population"},{"SettingName":"Population_MaxSimsInZone","Description":"Sets the maximum number of Sims that are allowed on a lot within the game. This can be set higher for people with higher-end machines, or lowered for those that have problems with the game lagging on public lots. The setting allows between 5 and 200 Sims. EA Default is 20.","MenuPath":"MCCC > MC Population > Other Settings > Maximum Sims In Zone","DefaultValue":"20","Module":"MC Population"},{"SettingName":"Population_BypassPlayedHouseholds","Description":"When considering Sims for moving single Sims out of households on lots into a new lot, or considering elder Sims to move into the retirement homes, bypass any played Sim households rather than just the active household if this setting is enabled.","MenuPath":"MCCC > MC Population > Moving Settings > Bypass Played Households","DefaultValue":"true","Module":"MC Population"},{"SettingName":"Population_AllowNoClowns","Description":"If true, then no clowns will be generated for random walk-by events. This will not prevent clowns from spawning by viewing Tragic Clown paintings, but random generation will not happen.","MenuPath":"MCCC > MC Population > Other Settings > Bypass Clown Walkby","DefaultValue":"False","Module":"MC Population"},{"SettingName":"Population_BarNights","Description":"Defines the desired nights for 'Bar Nights' that active Sims will be invited to. Any bar night not included from the list of available bar nights will no longer have invites sent-out by NPC Sims. Note that if an Active Sim is in a bar at 8:00PM on one of the unselected nights, NPC's for the special nights will still show-up. This just prevents all of the social invites and announcements from happening. Values are 'GU'-Guys Night, 'BE'-Bear Night, 'AL'-'Alien Night, 'GH'-Ghost Night, 'KN'-Knight Night, 'LA'-Ladies Night, 'SI'-Singles Night","MenuPath":"MCCC > MC Population > Enable or Disable Bar Nights","DefaultValue":"GU,BE,AL,GH,KN,LA,SI","Module":"MC Population"},{"SettingName":"Population_ReaperStopStalking","Description":"If true, the reaper will no longer be randomly spawned into public lots for things like dancing/clubbing/exercising/fishing/etc. The reaper will only show-up to reap Sims.","MenuPath":"MCCC > MC Population > Other Settings > No Reaper Stalking","DefaultValue":"False","Module":"MC Population"},{"SettingName":"Population_NumAdjustLot","Description":"Determines the valid lots to change the maximum Sims up to the 'Maximum Sims in Zone' setting. It is a comma-delimited list of values including 'WBY' for walkby, 'GYM' for Gym lots, 'LIB' for libraries, 'LOU' for lounges, 'BAR' for bars, 'CAF' for cafes, 'CHA' for the Chalet Gardens, 'CLU' for clubs, 'DAN' for Go Dancing situations, 'PAR' for parks, 'SPA' for spas, 'POL' for pools, and 'RES' for restaurants.","MenuPath":"MCCC > MC Population > Other Settings > Adjust Sims on Lot","DefaultValue":"All lot abbreviations.","Module":"MC Population"},{"SettingName":"Population_DisableImmortalSims","Description":"Enabling these settings will make the Sims grow old and die normally rather than live forever and never die on particular categories of Sims who EA defaults to no aging. Values include 'CL'-City Living Sims (Love Guru, City Repair, Weirdos, Busker Statues, etc.), 'JH'-Jasmine Holiday, 'GTW'-(Alien Pollinator, Criminals for the detective career), 'SV'-(Nanny, Butler), 'SN'-(Seasons: Scarecrows).","MenuPath":"MCCC > MC Population > Other Settings > Disable Immortal Sims","DefaultValue":"Blank for EA default","Module":"MC Population"},{"SettingName":"Population_EnforceVampireHomes","Description":"When enabled, this setting will only move Vampires into lots with the 'Registered Vampire Lair' lot trait. This applies to all mod moving-type situations: Homeless/Single Sims moving during MC Population scheduled runs, Marriage when two Sims have to decide which house they will move into. A Sim will be bypassed as a spouse or partner for Marriage and Pregnancy if one of the two Sims does not live in a vampire lot. Note that for marriage and pregnancy, Ancestral Homes conflict with Vampire Lots. A Sim on a vampire Lot will not be allowed to marry or become pregnant with a Sim on an Ancestral Home lot.","MenuPath":"MCCC > MC Population > Moving Settings > Enforce Vampire Homes","DefaultValue":"False","Module":"MC Population"},{"SettingName":"Occult_AbductionAges","Description":"For 'High' or 'Alien Invasion' options, this allows choosing the ages of Sims that will be abducted.","MenuPath":"MCCC > MC Occult > Aliens > Abduction Settings > Abduction Ages","DefaultValue":"'YA,A,E'","Module":"MC Occult"},{"SettingName":"Occult_AbductionAllowNPC","Description":"For 'High' or 'Alien Invasion' options, enabling this option will allow NPC's walking down the street around your house to be abducted in addition to Sims in your household.","MenuPath":"MCCC > MC Occult > Aliens > Abduction Settings > Allow NPC Abduction","DefaultValue":"false","Module":"MC Occult"},{"SettingName":"Occult_AbductionDuration","Description":"For 'High' or 'Alien Invasion' options, this allows setting the number of hours after Occult_AbductionStartHour that abductions may occur","MenuPath":"MCCC > MC Occult > Aliens > Abduction Settings > Abduction Time Length","DefaultValue":"6","Module":"MC Occult"},{"SettingName":"Occult_AbductionPregnancyAges","Description":"This defines the ages valid for pregnancy through abduction. This is separate from the MC Pregnancy age settings for pregnancy.","MenuPath":"MCCC > MC Occult > Aliens > Abduction Pregnancy Settings > Abduction Pregnancy Ages","DefaultValue":"'YA,A'","Module":"MC Occult"},{"SettingName":"Occult_AbductionPregnancyGenders","Description":"This defines the genders valid for pregnancy through abduction. This is separate from the MC Pregnancy gender settings for pregnancy.","MenuPath":"MCCC > MC Occult > Aliens > Abduction Pregnancy Settings > Abduction Pregnancy Genders","DefaultValue":"'M'","Module":"MC Occult"},{"SettingName":"Occult_AbductionStartHour","Description":"For 'High' or 'Alien Invasion' options, this allows setting the earliest time that alien abductions will occur. These are the hour with 0 being midnight and 23 being 11 PM.","MenuPath":"MCCC > MC Occult > Aliens > Abduction Settings > Abduction Start Time","DefaultValue":"22","Module":"MC Occult"},{"SettingName":"Occult_AlienFrequency","Description":"Set how often 'Alien Contact' interactions may cause results like Alien Abduction, Alien Visits and phonecalls. '0' = Zero abductions (Contact option on satellite never enables and Prevent Abductions will remain in effect constantly once chosen). 'N' = Normal EA settings. 'H' = High chance of abductions and visits (the Contact option on the satellite never disables). 'A' = Abductions almost constantly depending on the Occult_TimeBetweenAbductions setting.","MenuPath":"MCCC > MC Occult > Aliens > Abduction Settings > Abduction Frequency","DefaultValue":"'N'","Module":"MC Occult"},{"SettingName":"Occult_MaximumAliens","Description":"Sets a maximum number of desired aliens for the world. If the number of current aliens in the world is greater than or equal to this number then no more alien babies will be BORN. This does not change homeless aliens that the game generates, it only will prevent babies from being born as aliens.","MenuPath":"MCCC > MC Occult > Aliens > Maximum Aliens","DefaultValue":"-1 = No limit","Module":"MC Occult"},{"SettingName":"Occult_TimeBetweenAbductions","Description":"For 'High' or 'Alien Invasion' options, this allows setting the minimum number of hours between abductions.","MenuPath":"MCCC > MC Occult > Aliens > Abduction Settings > Hours Between Abductions","DefaultValue":"24","Module":"MC Occult"},{"SettingName":"Occult_ForceAlienDisguiseType","Description":"The default value uses EA's rules to determine whether an alien uses a disguise or not when they enter a lot. The 'Force Alien Disguise' option will make aliens wear their human disguise when they enter a lot. The 'Force Alien No Disguise' option will make aliens remove their human disguise when they enter a lot. Note that this does not change behavior on the alien homeworld lot. All aliens will remove their human disguises when entering the alien homeworld lot.","MenuPath":"MCCC > MC Occult > Aliens > Force Alien Disguise","DefaultValue":"''","Module":"MC Occult"},{"SettingName":"Occult_ForceDarkform","Description":"If this setting is enabled, when placing vampire Sims on lots, they will initially always be in their darkform. This can change if they feed or do something EA-situation-based to change them back but initially, they will always be in darkform.","MenuPath":"MCCC > MC Occult > Vampires > Force Darkform","DefaultValue":"false","Module":"MC Occult"},{"SettingName":"Occult_UseCustomPregnancy","Description":"If enabled, EA's default genetics may be overwritten by custom hybrid or alien Sim generation based on the percentages defined by the below alien/hybrid/human settings. This setting also allows vampire/human offspring percentages to be defined. If disabled, default EA rules will be used. Note that using the custom pregnancy rules in MC Occult, Alien parents will ALWAYS have alien babies and Vampire parents will ALWAYS have vampire babies.","MenuPath":"MCCC > MC Occult > Aliens > Other Pregnancy > Use Custom Pregnancy or MCCC > MC Occult > Vampires > Other Pregnancy > Use Custom Pregnancy","DefaultValue":"false","Module":"MC Occult"},{"SettingName":"Occult_MaximumVampires","Description":"Sets a maximum number of desired vampires for the world. If the number of current vampires in the world is greater than or equal to this number then no more vampire babies will be BORN. This does not change homeless vampires that the game generates, it only will prevent babies from being born as vampires.","MenuPath":"MCCC > MC Occult > Vampires > Maximum Vampires","DefaultValue":"-1 = No limit","Module":"MC Occult"},{"SettingName":"Occult_VampireExpAdjustment","Description":"Valid values are between -10 and 10 with zero being the default and providing no changes from EA's base progression. Negative values provide slower progression and positive values provide faster progression. -2 would be 2x slower than default progression. 2 would be 2x faster than default progression, etc.","MenuPath":"MCCC > MC Occult > Vampires > Experience Adjustment","DefaultValue":"0","Module":"MC Occult"},{"SettingName":"Occult_VampireSkillOnAgeUp","Description":"When this setting is enabled, NPC vampires will level-up as they age-up. They get one level per age-group starting at teen, so teens are fledglings, young adults are minor vampires, etc. When a vampire reaches elder, I do a check for the whole world to see if there is a grand master vampire anywhere. If there isn't, the vampire can become one. Otherwise, they will become a master. There will not be randomly-created multiple grand masters. Vampire Sims will also spend points on random powers and weaknesses as they level-up to give some variety to vampire Sims in the world. Note that to really take advantage of this, there has to be vampire aging in the world.","MenuPath":"MCCC > MC Occult > Vampire Settings > Level on Age-up","DefaultValue":"False","Module":"MC Occult"},{"SettingName":"Occult_RiskyVampPercentages","Description":"This allows the player to choose random chances that a Vampire Sim will pass along their vampirism to another Sim by accident through their bites. There are 4 percentage settings to determine different risky levels for different types of feeding. They include 'Ask for Permission to Drink', 'Compel for a Small Drink', 'Compel for a Deep Drink' and 'Drink Uncontrollably'. If a particular percentage is zero, then there is no risk for using that interaction.","MenuPath":"MCCC > MC Occult > Vampires > Risky Vampirism > Feeding Percentages","DefaultValue":"'0,0,0,0'","Module":"MC Occult"},{"SettingName":"Occult_RiskyVampNeedCreation","Description":"When using Risky Vampirism, this will determine if the Vampire Sim must have the 'Vampire Creation' power or not. If it's enabled, then no accidental vampires will be created unless the Vampire Sim has the 'Vampire Creation' power.","MenuPath":"MCCC > MC Occult > Vampires > Risky Vampirism > Only with Creation","DefaultValue":"True","Module":"MC Occult"},{"SettingName":"Dresser_RunOnAgeUp","Description":"A list of specific ages. When age-up to these specific ages happens, the 'dresser_clean' command will be run on the specified Sims. Values are 'T', 'YA', 'A' and 'E' and multiple ages may be specified comma-delimited, like 'T,YA,A'.","MenuPath":"MCCC > MC Dresser > Ages To Run On Age-up","DefaultValue":"'', for no cleanup for any ages.","Module":"MC Dresser"},{"SettingName":"Dresser_RunMakeupCheck","Description":"Whether or not to run mc_dresser against makeup. This checks to see if any makeup items are missing from Sims for any outfits. If so, and this setting is true, it will choose random white-list items for the makeup items. If no white-list makeup items are defined, it will not do anything. This functionality runs on Sims that match the Dresser_MakeupGenders and Dresser_MakeupAges settings. Sims not in the makeup gender and ages settings will get makeup removed when this runs. This is a timed cleanup that will run on Days 0, 2 and 4 at 12:00AM","MenuPath":"MCCC > MC Dresser > Makeup Settings > Run Makeup Check","DefaultValue":"false","Module":"MC Dresser"},{"SettingName":"Dresser_MakeupOutfits","Description":"This setting allows limitation of the outfits affected by Dresser_RunMakeupCheck. Valid categories are 'E'-Everyday, 'F'-Formal, 'P'-Party, 'AT'-Athletic, 'SW'-Swimwear and 'SL'-Sleepwear.","MenuPath":"MCCC > MC Dresser > Makeup Settings > Makeup Outfits","DefaultValue":"'E,F,P,AT,SW,SL'.","Module":"MC Dresser"},{"SettingName":"Dresser_ChangeOutfitAfterCareerF","Description":"Changes a female Sim's outfit from Career to the specified outfit category after coming-home from work. Any of the Dresser outfit categories are valid: (E, At, F, P, Sw, Sl).","MenuPath":"MCCC > MC Dresser > Female After Career Outfit","DefaultValue":"'' which leaves the career outfit on.","Module":"MC Dresser"},{"SettingName":"Dresser_ChangeOutfitAfterCareerM","Description":"Changes a male Sim's outfit from Career to the specified outfit category after coming-home from work. Any of the Dresser outfit categories are valid: (E, At, F, P, Sw, Sl).","MenuPath":"MCCC > MC Dresser > Male After Career Outfit","DefaultValue":"'' which leaves the career outfit on.","Module":"MC Dresser"},{"SettingName":"Dresser_OnlyUseSavedOutfits","Description":"If True, when Dresser Clean is run, if a saved outfit exists for a category, the saved outfit will be used rather than choosing random clothing.","MenuPath":"MCCC > MC Dresser > Only Use Saved Outfits","DefaultValue":"False","Module":"MC Dresser"},{"SettingName":"Dresser_PercentUseCustomSkinTone","Description":"Percentage chance when creating a new homeless NPC to use a custom skin tone defined in MC Dresser rather than EA default skin tone. If no skin tones are defined for the age/gender of the homeless Sim, then default skin tones are used.","MenuPath":"MCCC > MC Dresser > Percent Use Custom Skintone","DefaultValue":"0","Module":"MC Dresser"},{"SettingName":"Dresser_MakeupGenders","Description":"This settings specifies which genders are OK to put makeup, defined in MC Dresser Include Lists, on when running makeup cleaning and if a gender is not in this list (Males for example), then if they have any makeup, they will have it removed during cleaning.","MenuPath":"MCCC > MC Dresser > Makeup Settings > Makeup Genders","DefaultValue":"'F' for females","Module":"MC Dresser"},{"SettingName":"Dresser_MakeupAges","Description":"This setting specifies which ages are OK to put makeup, defined in MC Dresser Include Lists, on when running makeup cleaning and if an age is not in this list, then if they have any makeup, it will be removed during cleaning.","MenuPath":"MCCC > MC Dresser > Makeup Settings > Makeup Ages","DefaultValue":"'T,YA,A' for Teens, Young Adults and Adults","Module":"MC Dresser"},{"SettingName":"Dresser_PercentMultipleOutfits","Description":"Determines what percentage chance a Sim will be created with multiple outfits. 100% will always create multiple outfits when the game generates a Sim. If it's not 100%, then it will be based on a random roll.","MenuPath":"MCCC > MC Dresser > Multiple Outfit Settings > Multiple Outfit Percentage","DefaultValue":"0","Module":"MC Dresser"},{"SettingName":"Dresser_MaximumMultipleOutfits","Description":"The maximum random outfits to generate for a Sim. If this number is one, no additional outfits will ever be generated. This does not result in a random number of outfits being generated on a Sim. It will always generate this number in each applicable category. When new homeless Sims are generated by the game, if they match Dresser_MultipleOutfitGenders and Dresser_MultipleOutfitAges settings and if the Dresser_PercentMultipleOutfits is randomly matched, then they will be generated with the specified number of 'Maximum Outfits'. When a Sim ages-up, if the age they age-up into is within the Dresser_MultipleOutfitAges setting and their gender matches the Dresser_MultipleOutfitGenders, then they have a chance to have the 'Maximum Outfits' generated.","MenuPath":"MCCC > MC Dresser > Multiple Outfit Settings > Maximum Outfits","DefaultValue":"1","Module":"MC Dresser"},{"SettingName":"Dresser_MultipleOutfitAges","Description":"Ages that are valid for having multiple outfits generated.","MenuPath":"MCCC > MC Dresser > Multiple Outfit Settings > Multiple Outfit Ages","DefaultValue":"'C,T,YA,A,E' for 'Child', 'Teen', 'Young Adult', 'Adult' and 'Elder'","Module":"MC Dresser"},{"SettingName":"Dresser_MultipleOutfitGenders","Description":"Genders that are valid for having multiple outfits generated.","MenuPath":"MCCC > MC Dresser > Multiple Outfit Settings > Multiple Outfit Genders","DefaultValue":"'M,F' for 'Male' and 'Female'.","Module":"MC Dresser"},{"SettingName":"Dresser_ReplaceSituationOutfits","Description":"This setting allows replacing of 'Situation' outfits for various situations in the game where NPC's tend to dress in totally randomly generated, awful outfits. Rather than wearing the Situation outfits, this setting can be set for the different situations to wear a different outfit instead.","MenuPath":"MCCC > MC Dresser > Replace Situation Outfits","DefaultValue":"''","Module":"MC Dresser"},{"SettingName":"Dresser_IncludeDarkFormMakeup","Description":"The setting will only be visible if MC Occult is deployed as well and defaults to disabled but if enabled, it will work like MC Dresser makeup settings do for standard outfits. Makeup defined in the Include Lists will be put on Sims as applicable and makeup not defined as included items will be removed. Keep in mind that if you use special makeup looks on your vampires that you probably will not want to enable this setting, or you'll want to use the 'Bypass Outfit Changes' flag on all Sims you don't want to have makeup changed.","MenuPath":"MCCC > MC Dresser > Makeup Settings > Check Dark Form Makeup","DefaultValue":"False","Module":"MC Dresser"},{"SettingName":"Dresser_IncludeDarkFormOutfits","Description":"The setting will only be visible if MC Occult is deployed as well and defaults to disabled but if enabled, it will work like MC Dresser cleanup settings do for standard outfits. Anytime an Outfit Clean happens to a vampire Sim, in addition to cleaning standard outfits, all darkform outfits will be cleaned as well. Keep in mind that if you use special outfits on your vampires that you probably will not want to enable this setting, or you'll want to use the 'Bypass Outfit Changes' flag on all Sims you don't want to have outfits changed.","MenuPath":"MCCC > MC Dresser > Clean Dark Form Outfits","DefaultValue":"False","Module":"MC Dresser"},{"SettingName":"Club_BypassPlayedHouseholds","Description":"When considering Sims for filling empty club membership, bypass any played Sim households rather than just the active household if this setting is enabled.","MenuPath":"MCCC > MC Clubs > Bypass Played Households","DefaultValue":"true","Module":"MC Clubs"},{"SettingName":"Club_MonitorMembers","Description":"If enabled, periodically check clubs with open invites to determine if there are Sims in town eligible to fill the empty membership slots in those clubs. If there are, then the clubs are filled-up with eligible members.","MenuPath":"MCCC > MC Clubs > Monitor Club Members","DefaultValue":"false","Module":"MC Clubs"},{"SettingName":"Club_OpenMemberSlots","Description":"When Club Monitoring is enabled, the number in this setting will leave positions open in the clubs for manual filling if desired, rather than filling all the clubs in town that have any positions open so they're full. The default for the setting is 1 to leave a single open position in all clubs. Valid values are zero to 7. Please note that clubs already filled will not 'vacate' positions. Through time when the clubs have positions becoming available, this setting will just prevent them from fully filling-up again if that is the desire.","MenuPath":"MCCC > MC Clubs > Open Members","DefaultValue":"1","Module":"MC Clubs"},{"SettingName":"Cleaner_MatchGlasses","Description":"If a Sim has glasses in one outfit, populate it in all outfits except Bathing, Sleep and Swimming.","MenuPath":"MCCC > MC Cleaner > Item Cleaner > Sync Glasses","DefaultValue":"false","Module":"MC Cleaner"},{"SettingName":"Cleaner_SyncMarriedNames","Description":"This will sync-up married sims' last names, including the active lot. If MC Pregnancy is not deployed, it uses pretty simple logic right now, male last name taken in case of male/female couples and random last name used if both are the same sex. Otherwise, it will use the MC Marriage settings for determining last name. The household will be named to the new name if it was the other sim's name previously.","MenuPath":"MCCC > MC Cleaner > Sim Cleaner > Sync Married Names","DefaultValue":"true","Module":"MC Cleaner"},{"SettingName":"Cleaner_SyncHouseholdNames","Description":"If this is true, cleaner will occasionally rename households to match the last names of Sims living within them.","MenuPath":"MCCC > MC Cleaner > Neighborhood Cleaner > Sync Household Names","DefaultValue":"false","Module":"MC Cleaner"},{"SettingName":"Cleaner_CleanRelationships","Description":"This setting stores the two values necessary for MC Cleaner relationship cleaning. The first value is what type of Sims are affected by the cleaning. The valid values are 'N'-NPC Only, 'P'-NPC and Played, 'AO'-Only active Sims will have their relationships cleaned, 'PO'-Only played and inactive Sims will have their relationships cleaned and 'A'-All Sims including active Sims. The second value is what level of relationships to clean from the specified Sims. The valid values are 'Z'-Zero Level only, 'C'-Custom Level (Any value between 0 and 100 may be specified), 'A'-acquaintances or less, 'F'-friends or less, 'GF'-All relationships except significant others, 'S'-All relationships including significant others. No family members will be cleaned by this process. Note that absolute values are used for the scores. So if a custom setting of 20 is set and the relationship score is between -20 and 20, then the relationship will be deleted. The same is true for the other score types: Aquaintance, Friend, etc.","MenuPath":"MCCC > MC Cleaner > Relationship Cleaner > Sim Cleaner (2 buttons)","DefaultValue":"N,A","Module":"MC Cleaner"},{"SettingName":"Cleaner_BypassFamilyGhosts","Description":"When running the Clean Ghosts process, don't delete a ghost if they are in the family tree of the active family members.","MenuPath":"MCCC > MC Cleaner > Neighborhood Cleaner > Bypass Family Ghosts","DefaultValue":"True","Module":"MC Cleaner"},{"SettingName":"Cleaner_LeaveRelationshipCount","Description":"This setting will cause the relationship cleaning to stop when the specified number of relationships exist. So if 100 is specified, relationships will be cleaned per the relationship cleaning rules until 100 relationships exist. At that point, cleaning will stop.","MenuPath":"MCCC > MC Cleaner > Relationship Cleaner > Relationships to Leave","DefaultValue":"0","Module":"MC Cleaner"},{"SettingName":"Career_FillCareerInactiveOnly","Description":"When assigning careers to Sims, if this is true then any household marked 'Played' will be bypassed by the Sims 4 career-assignment process.","MenuPath":"MCCC > MC Career > Bypass Played Households","DefaultValue":"false","Module":"MC Career"},{"SettingName":"Logging_Enabled","Description":"Whether or not to log information messages from the different modules to mc_cmd_center.log","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Logging Settings > Message Logging","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Pause_On_Zone","Description":"Whether or not to auto-pause on screen transitions","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Pause on zone","DefaultValue":"false","Module":"MC Command Center"},{"SettingName":"Logging_Append","Description":"If this setting is true, then the logfile doesn't 'reset' to a blank file each time the game runs. It will append to the current log file. If it is false, then each time the game is restarted, the logfile gets restarted.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Logging Settings > Append to Logfile","DefaultValue":"false","Module":"MC Command Center"},{"SettingName":"Show_Sim_Menu_Type","Description":"This setting will control if and where a Sim Menu shows-up on Sims and the Relationship Panel with MC Command Center. Valid values include 'A'-All, 'ASH' - All with shift key, 'N'-None, 'S'-Show on Sims only, 'SSH' - Sim Menus with Shift Key, 'R'-Show on RelPanel only.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Show Menu Settings > Show Sim Menu","DefaultValue":"'A'","Module":"MC Command Center"},{"SettingName":"Show_Cheats_Menu_Type","Description":"Can be set to 'A' - All MC Cheats menus will be shown including the mailboxes of Sim lots with some world-affecting cheat commands and also on active Sims for Sim-specific cheat commands., 'ASH' - All with Shift Key, 'N' - No cheat menus.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Show Menu Settings > Show Cheats Menu","DefaultValue":"'A'","Module":"MC Command Center"},{"SettingName":"Show_Computer_Menu_Type","Description":"Can be set to 'A' - All MCCC Computer menus, 'ASH' - All with Shift Key, 'N' - No computer menus and the mc_settings console command has to be used to change settings.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Show Menu Settings > Show Computer Menu","DefaultValue":"'A'","Module":"MC Command Center"},{"SettingName":"Autosave_Enabled","Description":"Is auto-save functionality currently enabled?","MenuPath":"MCCC > MCCC Settings > Auto-Save > Use Auto-save","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Autosave_IntervalType","Description":"The valid interval types that can be selected for auto-saves are: Sim-Hour, Sim-Day, Real-world Hour or Pre-Alarms. The pre-alarm interval type will cause an automatic save to happen before midnight each Sim night before any MCCC alarms are run. If it is selected, Interval Amount is not used.","MenuPath":"MCCC > MCCC Settings > Auto-Save > Save Interval Type","DefaultValue":"Real-world Hour","Module":"MC Command Center"},{"SettingName":"Autosave_IntervalAmount","Description":"The amount of interval time-periods to delay between saves. For example, '1' Sim-Day. Maximum allowed is 24.","MenuPath":"MCCC > MCCC Settings > Auto-Save > Save Interval Amount","DefaultValue":"1","Module":"MC Command Center"},{"SettingName":"Autosave_MaxSaveNumber","Description":"The save games can go into different 'slots' if you want to have multiple saves at a time. The slot-number is increased each time a save happens until the maximum number of saves specified in this setting is reached. Maximum allowed is 10.","MenuPath":"MCCC > MCCC Settings > Auto-Save > Maximum Save Slot Number","DefaultValue":"1","Module":"MC Command Center"},{"SettingName":"Autosave_Name","Description":"The name to give the auto-save. This name will have the slot-number of the save appended to it so you will be able to more easily match save-game name with slot number on your file system.","MenuPath":"MCCC > MCCC Settings > Auto-Save > Auto-Save Name","DefaultValue":"MC Save","Module":"MC Command Center"},{"SettingName":"Autosave_HexSlotNumber","Description":"The slot number used by EA to save the game. The number entered here is a hexadecimal number which is used in the name on the file system. For example, '1111' in the settings file will be saved by EA as 'Slot_00001111.save'. The next save, if you have multiple enabled, will be 'Slot_00001112.save', etc.","MenuPath":"MCCC > MCCC Settings > Auto-Save > Auto-Save Slot-Number","DefaultValue":"1111","Module":"MC Command Center"},{"SettingName":"Show_Notifications","Description":"Whether or not to show wall-post notifications for in-game events like pregnancy, age-up, death and homeless move-ins. If this is disabled, all other show notification settings are disabled (Show_DeathNotifications, Show_AgeUpNotificationType, etc.)","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Notification Settings > Show Notifications","DefaultValue":"true","Module":"MC Command Center"},{"SettingName":"Show_AgeUpNotificationType","Description":"Will display a notification post when a Sim ages-up depending on whether the Sim falls within the limits of this setting. These include: '0'-No age-up notifications, 'N'-NPC's only, 'P'-Played/Active Sims only, 'R'-Sims related to the Active Sims only, 'AF'-Sims that are friends of the Active Sims only, 'AR'-Sims that are romantically involved with the Active Sims only or 'AL'-All Sims not in the active household will show notifications on age-up.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Notification Settings > Aging/Death Notification > Show Age-Up Notifications","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Show_DeathNotifications","Description":"Will display a notification post when a Sim dies and any inheritance occurring depending on whether the Sim falls within the limits of this setting. These include: '0'-No death notifications, 'N'-NPC's only, 'P'-Played/Active Sims only, 'R'-Sims related to the Active Sims only, 'AF'-Sims that are friends of the Active Sims only, 'AR'-Sims that are romantically involved with the Active Sims only or 'AL'-All Sims not in the active household will show notifications on death.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Notification Settings > Aging/Death Notifications > Show Death Notifications","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Show_NPCBirthdayNotifications","Description":"Will display a notification post when it is almost time for each NPC birthday.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Notification Settings > Aging/Death Notifications > Show NPC Birthday Notifications","DefaultValue":"false","Module":"MC Command Center"},{"SettingName":"Full_Edit_CAS","Description":"If enabled, when 'Modify in CAS' is used from the MC Command Center menu on a Sim, it will automatically run the 'cas.fulleditmode' cheat before opening CAS.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Console Command Settings > Enable Full Edit CAS","DefaultValue":"false","Module":"MC Command Center"},{"SettingName":"Decay_Ratio_Friendship","Description":"Allows slowing down or speeding-up the decay on friendship relationships. Lowering it from 100 will slow down the friendship decay. Putting it at 0 will stop the decay. Putting it above 100 will speed-up relationship decay making it more difficult to keep friendships (maximum of 500).","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Friendship Decay Percentage","DefaultValue":"100","Module":"MC Command Center"},{"SettingName":"Decay_Ratio_Romantic","Description":"Allows slowing down or speeding-up the decay on romantic relationships. Lowering it from 100 will slow down the romantic decay. Putting it at 0 will stop the decay. Putting it above 100 will speed-up relationship decay making it more difficult to keep romances (maximum of 500).","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Romantic Decay Percentage","DefaultValue":"100","Module":"MC Command Center"},{"SettingName":"Pay_Child_Support_Type","Description":"Determines if an additional expense will be added to active Household's weekly bill amount for each child they have that does not live on the active lot with them. This includes Teen or less in age. The amount is based on the value of the lot the Sim lives on, just like regular bills. Also, like regular bills, if your Sim has the Frugal trait, they will get a reduction in their child-support amount owed. Valid values are 'A'=All, 'M'=Married Only, 'U'=Unmarried Only or 'N'=None. 'Married Only' will only cause child support earnings or payments to happen if the parent Sims of the child are married. 'Unmarried Only' will only cause child support earnings or payments to happen if the parent Sims of the child are unmarried.","MenuPath":"MCCC > Money Settings > Pay Child Support Type","DefaultValue":"'N'","Module":"MC Command Center"},{"SettingName":"Game_Time_Speed","Description":"Sets the Sim-time-to-real-time. The lower this setting is, the faster the Sim's day runs which results in being able to accomplish less in a day. The higher it is, the longer the Sim day lasts. For example, to make a day last twice as long, the value could be set to 50. Important Note: Changing the Game Time Speed can have adverse affects on your game! The Sims 4 was not intended to have the Game Time Speed altered so doing so can cause issues with different behaviors in the game, especially those around timing and weather. I do not recommend using this setting! The only reason I haven't removed it from MCCC is because so many people DO want to use it despite the risks...","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Game Time Speed","DefaultValue":"25","Module":"MC Command Center"},{"SettingName":"Bill_Amount_Percent","Description":"Increases or decreases the weekly bill amount that must be paid by the active family when living in a house. 0 = No changes. -100 would be negative 100% of the normal bills…so that would make the bills each week be $0 unless child support is enabled. 100 would be positive 100% of the normal bills, so double the normal bill amount. This can go all the way up to 1000% if you're crazy or don't like electricity or something.","MenuPath":"MCCC > Money Settings > Change Bills Percent","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Testing_Cheats_Enabled","Description":"If enabled, EA's testing cheats are always turned-on when any family is played. It no longer has to be activated when changing played families.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Console Command Settings > Testing Cheats","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"BB_Debug_Objects_Enabled","Description":"If enabled, EA's Buy Debug cheat (bb.showhiddenobjects) is always enabled.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Console Command Settings > Build Buy Settings > BuyDebug Enabled","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"BB_Free_Build_Enabled","Description":"If enabled, EA's Free Build cheat (bb.enablefreebuild) is always enabled.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Console Command Settings > Build Buy Settings > Free Build Enabled","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"BB_Ignore_Unlocks_Enabled","Description":"If enabled, unlockables will show-up in build buy mode always using the EA bb.ignoregameplayunlocksentitlement cheat.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Console Command Settings > Build Buy Settings > Ignore Unlocks Enabled","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"BB_Move_Objects_Enabled","Description":"If enabled, EA's Move Objects cheat (bb.moveobjects) is always enabled.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Console Command Settings > Build Buy Settings > Move Objects Enabled","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Skill_Difficulty_Adjustment","Description":"This setting Increases/decreases the speed of Skill progression. Valid settings are from -50 to 10 with a default of zero. Negative is slower progress, positive is faster. Every negative point is -10%, so -10 is 100% slower, -20 is 200% slower, etc. Positive are 100% per point, so 2 is 200% faster up to 10 which is 1000% faster.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Skill Settings > Skill Difficulty Adjustment","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Debug_Cheats_Enabled","Description":"If enabled, when testing cheats are displayed by shift-left-clicking a Sim/Object, the EA Debug commands will also be displayed.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Console Command Settings > Debug Commands in Cheats","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Sim_Death_Only_On_Lot","Description":"If enabled, when a Sim dies either through gameplay or by using the 'Kill Sim' command, they will only have a reaper show-up and leave an urn/gravestone if they are on the current lot itself. If they are walking in the street, no reaper will appear. This is how the default gameplay works but if this setting is disabled, they can be reaped anywhere in the streets or current lot.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Sims Die On Lot","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"RelationshipCullingType","Description":"If the setting is 'D'-disabled, the EA relationship culling process that deletes Sims relationships after an amount of time with no contact will be deactivated. No relationship culling will occur. If the setting is 'E'-enabled, then the default EA relationship culling will occur. If MC Cleaner is deployed, an additional setting value of 'C' will be available. When this setting is used, MC Cleaner relationship cleaning will happen rather than EA's default relationship culling and it will follow the relationship cleaning rules as configured in MC Cleaner. After changing, the game must be restarted for the changes to take effect.","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Relationship Culling","DefaultValue":"'E'","Module":"MC Command Center"},{"SettingName":"Maximum_Household_Size","Description":"This setting allows overriding the default EA maximum household size of 8 to another value, up to 104. Note that when you have more than 8 Sims in a household, there are some in-game issues dealing with CAS. You have to use 'Modify in CAS' for the Sims that are after the first 8 in the household from the 'Sims Commands' menu. When a new update from EA comes-out, if you try to use the update when MCCC isn't updated, it could cause problems dealing with these households. This is the same as any household size change mod, but I just wanted to make sure it was noted here that these things should be kept in mind.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Maximum Household Size","DefaultValue":"8","Module":"MC Command Center"},{"SettingName":"Silence_Phone_Texts","Description":"This setting will determine what phone texts your active Sims get when their phone is silenced. Values include 'A'-All Texts, 'F'-Festival Only texts, 'N'-No Texts","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Phone Texts","DefaultValue":"A","Module":"MC Command Center"},{"SettingName":"Autosave_ShowConfirmation","Description":"When this is enabled, a confirmation dialog will be displayed when it is time for autosave to happen that allows saving to continue or optionally cancel the save for that time interval. If the setting is disabled, autosave always occurs at the scheduled intervals.","MenuPath":"MCCC > MCCC Settings->Auto-Save…->Show Confirmation Dialog","DefaultValue":"true","Module":"MC Command Center"},{"SettingName":"Pay_Child_Support_Percent","Description":"Determines the amount billed to a parent per child for child support. This is based on the Sim's total worth which includes lot value plus total funds. An amount between 1 and 1000 percent can be specified. 1% was the original default used by Child Support.","MenuPath":"MCCC Settings > Money Settings > Child Support Percent","DefaultValue":"1","Module":"MC Command Center"},{"SettingName":"Bill_AmountPercentApartment","Description":"Increases or decreases the weekly bill amount that must be paid by the active family living in apartments. 0 = No changes. -100 would be negative 100% of the normal bills…so that would make the bills each week be $0 unless child support is enabled. 100 would be positive 100% of the normal bills, so double the normal bill amount. Maximum is 1000%.","MenuPath":"MCCC > MCCC Settings > Money Settings > Apartment Billing Percent","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Headline_Effects_Enabled","Description":"If disabled, the Headline Effects such as plumbob will always be hidden upon loading the game. This functions the same as the headlineeffects console cheat command.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Console Command Settings > Headline Effects","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Hover_Effects_Enabled","Description":"If disabled, the Hovered Effects such as the white outline around Sims and objects will always be hidden upon loading the game. This functions the same as the hovereffects console cheat command.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Console Command Settings > Hover Effects","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Bill_AutoPay","Description":"If this setting is enabled, when bills are generated weekly, if the active household has the funds available to pay due bills, they are automatically deducted from available funds.","MenuPath":"MCCC > MCCC Settings > Money Settings > Auto-pay Bills","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Adopt_Neglected_Child","Description":"When enabled, if the game decides that a baby, toddler, infant or child is neglected and needs to be taken away from the active household, another household will adopt them rather than social services taking them to limbo never to be seen again.","MenuPath":"MCCC Settings > Gameplay Settings > Adopt Neglected Child","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Allow_Teen_Parenting","Description":"When enabled, Teens acquire the parenting skill just like adults.","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Allow Teen Parenting","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Appearance_AF_Template","Description":"The ranges for an Adult Female for each body part. Individual body parts are included within this setting, but it is NOT recommended to manually edit them in the settings file.","MenuPath":"MCCC > MC CAS > Define Appearance Template > Female > Adult > (body part selection)","DefaultValue":"All body part ranges default to '-100,100', which is EA's default ranges.","Module":"MC CAS"},{"SettingName":"Appearance_AM_Template","Description":"The ranges for an Adult Male for each body part. Individual body parts are included within this setting, but it is NOT recommended to manually edit them in the settings file.","MenuPath":"MCCC > MC CAS > Define Appearance Template > Male > Adult > (body part selection)","DefaultValue":"All body part ranges default to '-100,100', which is EA's default ranges.","Module":"MC CAS"},{"SettingName":"Appearance_ApplyTemplate","Description":"When the template settings will be applied to Sims within the game. Blank is manual and the templates will only be applied when the user applies a template on a Sim from the MC CAS Sim Menu. 'A' is Age-up and the templates will be applied to Sims when they age-up into the ages covered by the templates. This is the most efficient automatic template application process as it only happens on the individual Sims when they age-up. 'Z' is when the Sims zone-into the current zone, the template will be applied to them. This is the least efficient automatic template application process as it happens to every Sim when they zone-in, regardless if the template has already been applied to them.","MenuPath":"MCCC > MC CAS > Apply Appearance Template","DefaultValue":"Blank (Manual) is the default","Module":"MC CAS"},{"SettingName":"Appearance_EF_Template","Description":"The ranges for an Elder Female for each body part. Individual body parts are included within this setting, but it is NOT recommended to manually edit them in the settings file.","MenuPath":"MCCC > MC CAS > Define Appearance Template > Female > Elder > (body part selection)","DefaultValue":"All body part ranges default to '-100,100', which is EA's default ranges.","Module":"MC CAS"},{"SettingName":"Appearance_EM_Template","Description":"The ranges for an Elder Male for each body part. Individual body parts are included within this setting, but it is NOT recommended to manually edit them in the settings file.","MenuPath":"MCCC > MC CAS > Define Appearance Template > Male > Elder > (body part selection)","DefaultValue":"All body part ranges default to '-100,100', which is EA's default ranges.","Module":"MC CAS"},{"SettingName":"Appearance_FemaleFitLimits","Description":"The Upper and Lower limits that should be allowed on female Sims for 'fit'. Values are from -100 (No muscles and skinny) to 100 (Bulky muscles).","MenuPath":"MCCC > MC CAS > Female Fit/Fat Limits (2 buttons)","DefaultValue":"'-100,100'","Module":"MC CAS"},{"SettingName":"Appearance_FemaleLeanLimits","Description":"The Upper and Lower limits that should be allowed on female Sims for 'fat'. Values are from -100 (No fat, bony), to 100 (Fat).","MenuPath":"MCCC > MC CAS > Female Fit/Fat Limits (2 buttons)","DefaultValue":"'-100,100'","Module":"MC CAS"},{"SettingName":"Appearance_MaleFitLimits","Description":"The Upper and Lower limits that should be allowed on male Sims for 'fit'. Values are from -100 (No muscles and skinny) to 100 (Bulky muscles).","MenuPath":"MCCC > MC CAS > Male Fit/Fat Limits (2 buttons)","DefaultValue":"'-100,100'","Module":"MC CAS"},{"SettingName":"Appearance_MaleLeanLimits","Description":"The Upper and Lower limits that should be allowed on male Sims for 'fat'. Values are from -100 (No fat, bony), to 100 (Fat).","MenuPath":"MCCC > MC CAS > Male Fit/Fat Limits (2 buttons)","DefaultValue":"'-100,100'","Module":"MC CAS"},{"SettingName":"Appearance_MonitorPhysique","Description":"Whether or not to monitor 'fit' and 'fat' changes in Sims and keep them within specified limits. This currently happens when a Sim is 'instanced', which basically means when a zone is loaded with the Sim within it or when they come into the zone afterwards. This must be true for anything to happen with Appearance_MaleFitLimits, Appearance_MaleLeanLimits, Appearance_FemaleFitLimits and Appearance_FemaleLeanLimits. These settings currently only apply to Teens, Young Adults and Adults","MenuPath":"MCCC > MC CAS > Monitor Physique","DefaultValue":"false","Module":"MC CAS"},{"SettingName":"Appearance_TF_Template","Description":"The ranges for an Teen Female for each body part. Individual body parts are included within this setting, but it is NOT recommended to manually edit them in the settings file.","MenuPath":"MCCC > MC CAS > Define Appearance Template > Female > Teen > (body part selection)","DefaultValue":"All body part ranges default to '-100,100', which is EA's default ranges.","Module":"MC CAS"},{"SettingName":"Appearance_TM_Template","Description":"The ranges for an Teen Male for each body part. Individual body parts are included within this setting, but it is NOT recommended to manually edit them in the settings file.","MenuPath":"MCCC > MC CAS > Define Appearance Template > Male > Teen > (body part selection)","DefaultValue":"All body part ranges default to '-100,100', which is EA's default ranges.","Module":"MC CAS"},{"SettingName":"Appearance_YAF_Template","Description":"The ranges for an Young Adult Female for each body part. Individual body parts are included within this setting, but it is NOT recommended to manually edit them in the settings file.","MenuPath":"MCCC > MC CAS > Define Appearance Template > Female > Young Adult > (body part selection)","DefaultValue":"All body part ranges default to '-100,100', which is EA's default ranges.","Module":"MC CAS"},{"SettingName":"Appearance_YAM_Template","Description":"The ranges for an Young Adult Male for each body part. Individual body parts are included within this setting, but it is NOT recommended to manually edit them in the settings file.","MenuPath":"MCCC > MC CAS > Define Appearance Template > Male > Young Adult > (body part selection)","DefaultValue":"All body part ranges default to '-100,100', which is EA's default ranges.","Module":"MC CAS"},{"SettingName":"Appearance_UseParentAppearance","Description":"If enabled, a teenager's body appearance will be more like their parent. The fitness/fatness of the Teen will be a random value within the ranges of their parent values. Each body part appearance will be the same as the parent that they share a gender with, or a random value within the ranges of their parent values if both parents are the same gender as the Teen. The values here will have random variance based on the Appearance_ParentAppearanceVariance setting, if applicable.","MenuPath":"MCCC > MC CAS > Offspring > Use Parent Physical Attributes","DefaultValue":"false","Module":"MC CAS"},{"SettingName":"Appearance_UseParentSkinTones","Description":"If one of the two parents of a baby Sim has a custom skintone, rather than averaging the skintones used by the parents for the child, it will randomly use either one or the other of the parent's skintones. This will prevent some weird skintones that babies would get when using custom skintones in your game.","MenuPath":"MCCC > MC CAS > Offspring > Use Parent Skintones","DefaultValue":"false","Module":"MC CAS"},{"SettingName":"Appearance_ParentAppearanceVariance","Description":"This setting works with 'Appearance_UseParentAppearance' setting. This allows entry of a percentage number that the offspring's physical values could vary by from the parent's physical values. It defaults to 0%, which would make the child's physical attributes look exactly like their parent. It can go up to 100%, but this would probably be pretty silly since if it was that high, you'd probably just not want to use the Parent Physical Attributes anyway. 10% is probably a good example of a number that would cause some deviation between the parent and child, but not a great deal. Note that this value is plus or minus. So a setting of 10 would allow the values to be 10% less than the parent's values or 10% more.","MenuPath":"MCCC > MC CAS > Offspring > Parent Values Variance Percent","DefaultValue":"0","Module":"MC CAS"},{"SettingName":"Appearance_DefaultWalkstyle_AF","Description":"When set from the UI, all existing adult female Sims will have their walkstyles changed from the default to whatever is entered here. From then on, if Appearance_AgeupChangeWalkstyle is enabled, then when female Sims age-up to adults, they will have their walkstyle changed to this value. Any adult female Sims generated by the game will also use this walkstyle.","MenuPath":"MCCC > MC CAS > Walkstyle Settings > Set Default Walkstyle > Female > Adult","DefaultValue":"Sims 4 Default walkstyle","Module":"MC CAS"},{"SettingName":"Appearance_DefaultWalkstyle_AM","Description":"When set from the UI, all existing adult male Sims will have their walkstyles changed from the default to whatever is entered here. From then on, if Appearance_AgeupChangeWalkstyle is enabled, then when male Sims age-up to adults, they will have their walkstyle changed to this value. Any adult male Sims generated by the game will also use this walkstyle.","MenuPath":"MCCC > MC CAS > Walkstyle Settings > Set Default Walkstyle > Male > Adult","DefaultValue":"Sims 4 Default walkstyle","Module":"MC CAS"},{"SettingName":"Appearance_DefaultWalkstyle_EF","Description":"When set from the UI, all existing elder female Sims will have their walkstyles changed from the default to whatever is entered here. From then on, if Appearance_AgeupChangeWalkstyle is enabled, then when female Sims age-up to elders, they will have their walkstyle changed to this value. Any elder female Sims generated by the game will also use this walkstyle.","MenuPath":"MCCC > MC CAS > Walkstyle Settings > Set Default Walkstyle > Female > Elder","DefaultValue":"Sims 4 Default walkstyle","Module":"MC CAS"},{"SettingName":"Appearance_DefaultWalkstyle_EM","Description":"When set from the UI, all existing elder male Sims will have their walkstyles changed from the default to whatever is entered here. From then on, if Appearance_AgeupChangeWalkstyle is enabled, then when male Sims age-up to elders, they will have their walkstyle changed to this value. Any elder male Sims generated by the game will also use this walkstyle.","MenuPath":"MCCC > MC CAS > Walkstyle Settings > Set Default Walkstyle > Male > Elder","DefaultValue":"Sims 4 Default walkstyle","Module":"MC CAS"},{"SettingName":"Appearance_DefaultWalkstyle_TF","Description":"When set from the UI, all existing teen female Sims will have their walkstyles changed from the default to whatever is entered here. From then on, if Appearance_AgeupChangeWalkstyle is enabled, then when female Sims age-up to teens, they will have their walkstyle changed to this value. Any teen female Sims generated by the game will also use this walkstyle.","MenuPath":"MCCC > MC CAS > Walkstyle Settings > Set Default Walkstyle > Female > Teen","DefaultValue":"Sims 4 Default walkstyle","Module":"MC CAS"},{"SettingName":"Appearance_DefaultWalkstyle_TM","Description":"When set from the UI, all existing male teen Sims will have their walkstyles changed from the default to whatever is entered here. From then on, if Appearance_AgeupChangeWalkstyle is enabled, then when male Sims age-up to teens, they will have their walkstyle changed to this value. Any teen male Sims generated by the game will also use this walkstyle.","MenuPath":"MCCC > MC CAS > Walkstyle Settings > Set Default Walkstyle > Male > Teen","DefaultValue":"Sims 4 Default walkstyle","Module":"MC CAS"},{"SettingName":"Appearance_DefaultWalkstyle_YAF","Description":"When set from the UI, all existing young adult female Sims will have their walkstyles changed from the default to whatever is entered here. From then on, if Appearance_AgeupChangeWalkstyle is enabled, then when female Sims age-up to young adults, they will have their walkstyle changed to this value. Any young adult female Sims generated by the game will also use this walkstyle.","MenuPath":"MCCC > MC CAS > Walkstyle Settings > Set Default Walkstyle > Female > Young Adult","DefaultValue":"Sims 4 Default walkstyle","Module":"MC CAS"},{"SettingName":"Appearance_DefaultWalkstyle_YAM","Description":"When set from the UI, all existing young adult male Sims will have their walkstyles changed from the default to whatever is entered here. From then on, if Appearance_AgeupChangeWalkstyle is enabled, then when male Sims age-up to young adults, they will have their walkstyle changed to this value. Any young adult male Sims generated by the game will also use this walkstyle.","MenuPath":"MCCC > MC CAS > Walkstyle Settings > Set Default Walkstyle > Male > Young Adult","DefaultValue":"Sims 4 Default walkstyle","Module":"MC CAS"},{"SettingName":"Appearance_AgeupChangeWalkstyle","Description":"When enabled, upon aging-up non-active Sims will change from whatever their current walkstyle is to the walkstyle defined in the Appearance_DefaultWalkstyle settings. This will overwrite any walkstyle they currently are using with whatever is in the settings even if the setting is 'Default Walkstyle'.","MenuPath":"MCCC > MC CAS > Walkstyle Settings > Change Walkstyles on Age Up","DefaultValue":"False","Module":"MC CAS"},{"SettingName":"CAS_BypassBlueBabies","Description":"If this setting is enabled, then any babies in human form will be forced to use a 'human' color. Hybrid babies will not be blue/green/purple and the blue/green colors in EA's default CAS skin tones will also be blocked. If this setting is disabled, which is the default setting, then EA's baby generation code will determine what skin-color all babies have and I just let it through as-is.","MenuPath":"MCCC > MC CAS > Offspring > Bypass Blue Babies","DefaultValue":"False","Module":"MC CAS"},{"SettingName":"Tuner_AllowTeenAskMoveIn","Description":"When enabled, active Teen Sims will be allowed to invite other Sims to move-in to the active household. Also, active Sims will be allowed to invite teen NPC Sims to move-in to the active household.","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior > Allow Teen Move-in","DefaultValue":"false","Module":"MC Tuner"},{"SettingName":"Show_MovingNotificationType","Description":"Determines whether to display a notification post when a Sim moves into a new household (not counting elder retirement home moves, which have never sent notifications) depending on whether the Sim falls within the limits of this setting. These include: '0'-No moving notifications, 'N'-NPC's only, 'P'-Played/Active Sims only, 'R'-Sims related to the Active Sims only, 'AF'-Sims that are friends of the Active Sims only, 'AR'-Sims that are romantically involved with the Active Sims only or 'AL'-All Sims not in the active household will show notifications on moving.","MenuPath":"MCCC Settings > Notification/Console/Menu Settings > Notification Settings > MC Population Notifications > Show Moving Notifications","DefaultValue":"'0'","Module":"MC Command Center"},{"SettingName":"Career_ChildrenQuitSchool","Description":"If these settings are enabled, a new option will be available in Sim Commands when clicking on a child Active Sim to allow them to Quit School. Note that the 'Resume School' command also in the Sims menu on those same children are the only way for the children to go back to school. Also note that if a child resumes school, they will be at a low grade-point and will have to work their way back-up to whatever their grade was previously.Whenever this setting is enabled, Children cannot go to scouts and stay in school. To quit school, it must become a job that can be quit. Sims 4 does not allow more than one job at a time so it has to be school or scouts, both of which count as jobs.","MenuPath":"MCCC > MC Career > Children Quit School","DefaultValue":"false","Module":"MC Career"},{"SettingName":"Career_TeensQuitSchool","Description":"If these settings are enabled, a new option will be available in Sim Commands when clicking on a teen Active Sim to allow them to Quit School. Note that the 'Resume School' command also in the Sims menu on those same teens are the only way for the teen to go back to school. Also note that if a teen resumes school, they will be at a low grade-point and will have to work their way back-up to whatever their grade was previously. Whenever this setting is enabled, Teens cannot get a part-time job and stay in school. To quit school, it must become a job that can be quit. Sims 4 does not allow more than one job at a time so it has to be school or another job.","MenuPath":"MCCC > MC Career > Teens Quit School","DefaultValue":"false","Module":"MC Career"},{"SettingName":"Occult_AlienPollinatorGenders","Description":"Valid genders for the alien pollinator may be set to Male, Female or both. In the case of 'both', a gender will be randomly selected. Note that there is only one pollinator in the world at a time so if a pollinator already exists, another will not be created using the new settings. This setting is only used when a new alien pollinator is created.","MenuPath":"MCCC > MC Occult > Aliens > Abduction Pregnancy Settings > Pollinator Gender","DefaultValue":"'F'","Module":"MC Occult"},{"SettingName":"Pregnancy_AdoptionPercentMale","Description":"Allows a percent to be entered for male/female chances of adopted children generated during scheduled random pregnancy alarms. Note that this has no effect on active Sim adoption through computers. Previously, genders defined in Offspring Gender were used and there was always a 50/50 chance. If 0 is specified, only female children will be adopted. If 100 is specified, only male children will be adopted.","MenuPath":"MCCC > MC Pregnancy > Adoption Settings > Adoption Percent Male","DefaultValue":"50","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_OppositeSexAdoptionPercent","Description":"This works just like the setting for same sex couples. At the point that a pregnancy would be generated, if the percentage check passes then a child will be adopted instead. It doesn't happen at the point the baby would be born but at the point the pregnancy would be started. So if Sims are already pregnant, they will have babies, not adopt.","MenuPath":"MCCC > MC Pregnancy > Adoption Settings > Opposite Sex Adoption Percent","DefaultValue":"0","Module":"MC Pregnancy"},{"SettingName":"Population_AllowHomelessMoveIn","Description":"Allow Sims in homeless households to populate empty houses on lots in the different neighborhoods. Only houses with at least one bed in the Lot info will be valid for move-in.","MenuPath":"MCCC > MC Population > Moving Settings > Allow Homeless Move-In","DefaultValue":"true","Module":"MC Population"},{"SettingName":"Pregnancy_BabyMotiveDecay","Description":"This setting allows altering the rate at which a baby's motives decay. 100, which is the default, results in normal baby motive decay. Below 100 reduces the rate at which babies motives decay. 50 = half the normal motive decay rate. 0 = no motive decay. etc. Going above 100 (up to 500) increases the rate at which babies motive decay making babies MORE needy.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Motive Decay > Baby Motive Decay Percent","DefaultValue":"100","Module":"MC Command Center"},{"SettingName":"MotiveDecay_Cats","Description":"Alters the rate at which the motives decay for Cats. 100, which is the default, results in normal motive decay. Below 100 reduces the rate at which motives decay. 50 = half the normal motive decay rate. 0 = no motive decay. etc. Going above 100 (up to 500) increases the rate at which motive decay making them drop 2x faster than default EA levels. Traits and buffs that affect Motive decay will still apply to the new decay rate as well unless it's set to zero.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Motive Decay > Cat Motive Decay Percent","DefaultValue":"100","Module":"MC Command Center"},{"SettingName":"MotiveDecay_Dogs","Description":"Alters the rate at which the motives decay for Dogs. 100, which is the default, results in normal motive decay. Below 100 reduces the rate at which motives decay. 50 = half the normal motive decay rate. 0 = no motive decay. etc. Going above 100 (up to 500) increases the rate at which motive decay making them drop 2x faster than default EA levels. Traits and buffs that affect Motive decay will still apply to the new decay rate as well unless it's set to zero.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Motive Decay > Dog Motive Decay Percent","DefaultValue":"100","Module":"MC Command Center"},{"SettingName":"MotiveDecay_Sims","Description":"Alters the rate at which the motives decay for Sims. 100, which is the default, results in normal motive decay. Below 100 reduces the rate at which motives decay. 50 = half the normal motive decay rate. 0 = no motive decay. etc. Going above 100 (up to 500) increases the rate at which motive decay making them drop 2x faster than default EA levels. Traits and buffs that affect Motive decay will still apply to the new decay rate as well unless it's set to zero.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Motive Decay > Sim Motive Decay Percent","DefaultValue":"100","Module":"MC Command Center"},{"SettingName":"MotiveDecay_Vampires","Description":"Alters the rate at which the motives decay for Sims. 100, which is the default, results in normal motive decay. Below 100 reduces the rate at which motives decay. 50 = half the normal motive decay rate. 0 = no motive decay. etc. Going above 100 (up to 500) increases the rate at which motive decay making them drop 2x faster than default EA levels. Traits and buffs that affect Motive decay will still apply to the new decay rate as well unless it's set to zero.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Motive Decay > Vampire Motive Decay Percent","DefaultValue":"100","Module":"MC Command Center"},{"SettingName":"Tuner_ArchiveInteractions","Description":"If enabled, in addition to interactions currently running on Sims, the 'Currently Running Scan' dialog will also display archived interactions that have happened recently.","MenuPath":"MCCC > MC Tuner > Autonomy Scan > Archive Autonomous Actions","DefaultValue":"false","Module":"MC Tuner"},{"SettingName":"Tuner_MaximumArchive","Description":"Specifies the maximum number of interactions to archive per Sim for the Currently Running Scan autonomy dialog.","MenuPath":"MCCC > MC Tuner > Autonomy Scan > Maximum Autonomy Archive","DefaultValue":"50","Module":"MC Tuner"},{"SettingName":"Pregnancy_PetAgeToRun","Description":"These are the ages that pets will be valid to have random pregnancies. It can be Adult and/or Elder. It is recommend to not ONLY set it on elder unless the pet age span for elders is pretty large. Otherwise, you'll have them dying before their babies get very old.","MenuPath":"MCCC > MC Pregnancy > Pet Pregnancy Settings > Age to Run","DefaultValue":"'A' for Adult.","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_PetAllowHomeless","Description":"When enabled, homeless Pets (not including strays) are eligible as targets for random pregnancies. This is specifically used for determining valid targets. Any other male pet of the same species will be valid as a partner to a target whether they are homeless or strays.","MenuPath":"MCCC > MC Pregnancy > Pet Pregnancy Settings > Allow Homeless Pregnancy","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_PetMaxHouseholdChildren","Description":"This number determines the maximum number of children that a pet have through pregnancies in their lifetime. Values are from 1 to 50.","MenuPath":"MCCC > MC Pregnancy > Pet Pregnancy Settings > Maximum Household Children","DefaultValue":"3","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_PetMaxOffspring","Description":"Maximum allowable offspring. This just limits the number of babies to not be greater than the specified number. The maximum value for this setting is 6.","MenuPath":"MCCC > MC Pregnancy > Pet Pregnancy Settings > Maximum Offspring","DefaultValue":"3","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_PetPartnerAge","Description":"These are the ages that pets are eligible to be a partner for a pregnant Pet of the same species.","MenuPath":"MCCC > MC Pregnancy > Pet Pregnancy Settings > Partner Age","DefaultValue":"'A' for Adult.","Module":"MC Pregnancy"},{"SettingName":"Show_PetPregnancyNotificationType","Description":"Will display a notification post when a Pet gets pregnant depending on whether the Pet falls within the limits of this setting. These include: '0'-No pregnancy notifications, 'N'-NPC's only, 'P'-Played/Active Pets only, 'R'-Pets related to an active Pet only or 'AL'-All Pets not in the active household will show pregnancy notifications.","MenuPath":"MCCC > MC Pregnancy > Pet Pregnancy Settings > Show Pregnancy Notifications","DefaultValue":"'0'","Module":"MC Command Center"},{"SettingName":"Pregnancy_SyncChildSurname","Description":"If enabled, when a child is adopted through MC Pregnancy or their parent marries another Sims through the random marriage process, their last name will be synced with the parents. There are some rules to this: 1) If it's an adoption and the 'Rename Non-Active Adoptions' setting is used and is valid for the child, then automatic renaming won't happen as the player has chosen to use manual renaming instead. Also, both parents have to already have the same surname or no rename will occur. 2) If it's a marriage, the renaming only happens if: the parents move into the same household as a result of the marriage and the child lives in the same household, and the parents both end-up with the same last name based on MC Marriage last name rules.","MenuPath":"MCCC > MC Pregnancy > Offspring > Sync Child Surname","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Relationship_BreakupMoveoutOffspring","Description":"Whenever a Sim moves-out from a breakup, this setting is the percentage chance that offspring that are a child or younger will move with the Sim moving-out. If it's 0, they will stay with the Sim remaining in the original house.","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Auto-Relationship Settings > Breakup Settings > Move Children with Breakup","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Relationship_BreakupMoveoutSim","Description":"This setting helps to determine which Sim of the couple will move-out if a breakup occurs. Note that they will be moved into a homeless household! They will not be moved into a lot, even if they were living in a lot previously! If it is zero, no move-outs will happen. Otherwise, if the parents of either couple are living with the Sims, the other Sim will move-out by default. If that's not the case, then for an opposite-sex couple, either the Male or Female Sim may be selected to move-out. It can also be selected for a random Sim to move-out. If a Same-sex couple breaks-up, they will use the Random setting rather than Male or Female if that is selected.","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Auto-Relationship Settings > Breakup Settings > Breakup Move-out Sim","DefaultValue":"1","Module":"MC Command Center"},{"SettingName":"Relationship_BreakupPercent","Description":"This setting controls relationship changes between Sims that are couples, but not married. If it has a zero value, like it does by default, then no breakups will occur. Otherwise, for everything that may either raise or lower the relationship between two Sims (and there are a few things that can), this percent is checked to determine if it should apply the modifier to the relationship or not. After all factors are checked, the relationship can either improve or decline. If it declines enough so either the friendship or romance levels between the two Sims drops below zero, then a breakup will happen.","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Auto-Relationship Settings > Breakup Settings > Couple Relationship Change Percent","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Show_RelChangeNotificationType","Description":"This works like all other 'Notification Type' settings. It allows choosing specifically which Sims you want to see the notifications about any relationship changes that happen as a result of the scheduled process. It can be set to none, all, related Sims, active Sims only, played Sims, etc. The default is 'None'. As a note, if logging is enabled, a couple of details will be logged to the mc_cmd_center.log file when the relationship change process runs as well, no matter the setting value.","MenuPath":"MCCC Settings > Notification/Console/Menu Settings > Notification Settings > MC Pregnancy Notifications > Show Relationship Changes","DefaultValue":"'0' for None","Module":"MC Command Center"},{"SettingName":"Cleaner_CleanCulled","Description":"If a Sim has been marked as culled by the Sims 4 or is a ghost and is released to the netherworld, delete them from the game once a week (Day 0, 12:00AM).","MenuPath":"MCCC > MC Cleaner > Neighborhood Cleaner > Clean Culled Sims","DefaultValue":"false","Module":"MC Cleaner"},{"SettingName":"Relationship_BreakupMarriagePercent","Description":"This setting controls relationship changes between Sims that are married. If it has a zero value, like it does by default, then no breakups will occur. Otherwise, for everything that may either raise or lower the relationship between two Sims (and there are a few things that can), this percent is checked to determine if it should apply the modifier to the relationship or not. After all factors are checked, the relationship can either improve or decline. If it declines enough so either the friendship or romance levels between the two Sims drops below zero, then a breakup will happen.","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Auto-Relationship Settings > Breakup Settings > Spouse Relationship Change Percent","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Tuner_AllowMultipleBFFs","Description":"If enabled, there is no limit to the number of BFFs a Sim may have.","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior > Allow Multiple BFFs","DefaultValue":"False","Module":"MC Tuner"},{"SettingName":"Pregnancy_AllowMalePregnancy","Description":"Determines what male pregnancy is allowed. It can be set to 'Allow Pregnancy' (males can become pregnant), 'No Pregnancy' (males will never become pregnant) and 'Same Sex Only' (males will only become pregnant with other male Sims). This setting affects the random NPC pregnancy that happens on scheduled nights, not Woohoo/Try for Baby as there are already settings for the same there.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Male Pregnancy","DefaultValue":"N","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_AgePercentage","Description":"The 'try for baby' percentage used when testing for random NPC pregnancies. It can be separately set for the each age groups. 0 will turn-off random pregnancies for NPC's for that age group. Note that Teens will only be available for this setting if the MC Woohoo module is deployed.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Pregnancy Percentage","DefaultValue":"20 for all ages","Module":"MC Pregnancy"},{"SettingName":"Occult_AgePercentage","Description":"This is the percentage chance that a Sim will become pregnant through abduction. It can be separately set for the Teen, Young Adult, Adult and Elder age groups. A number between 0 and 100 can be specified. 0 will turn-off abduction pregnancies.","MenuPath":"MCCC > MC Occult > Aliens > Abduction Pregnancy Settings > Abduction Pregnancy Percent","DefaultValue":"30","Module":"MC Occult"},{"SettingName":"Marriage_AgePercentage","Description":"The percentage chance that random NPC marriage will happen to eligible NPC Sims. It can be separately set for each age groups. 0 will turn-off random marriages for NPC's for that age group. Note that Teens will only be available for this setting if the MC Woohoo module is deployed.","MenuPath":"MCCC > MC Pregnancy > Marriage Sim Selection > Marriage Percentage","DefaultValue":"20 for all ages","Module":"MC Marriage"},{"SettingName":"Show_PetDeathNotificationType","Description":"Will display a notification post when a Pet dies depending on whether the Pet falls within the limits of this setting. These include: '0'-No death notifications, 'N'-NPC's only, 'P'-Played Pets only or 'AL'-All Pets not in the active household will show notifications on death.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Notification Settings > Aging/Death Notifications > Show Pet Death Notifications","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Occult_RiskyVampNotification","Description":"When this is enabled, if a Sim is turned into a vampire through Risky Vampirism, the player will receive a notification that it happened.","MenuPath":"MCCC > MC Occult > Vampires > Risky Vampirism > Vampire Creation Notification","DefaultValue":"false","Module":"MC Occult"},{"SettingName":"Pregnancy_OffspringTraitsType","Description":"Determines what type of inheritance MC Pregnancy will use to determine the traits a baby inherits. The different types are 'Inherit No Traits', 'Inherit Maximum Number' which will always inherit the specified maximum number of traits unless there aren't that many valid traits available for the baby to inherit, and 'Inherit Random Number' which inherits between 1 and the maximum number of traits for each offspring just to give some variety. The default for this setting is 'Inherit No Traits' so offspring will not inherit any traits unless it is changed.","MenuPath":"MCCC > MC Pregnancy > Offspring > Inherit Trait Type","DefaultValue":"N","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_OffspringTraitsMax","Description":"Determines the maximum number of traits from both parents each baby will inherit. This can be between 1 and 20 with 2 being the default. Personally, I think less is better but I know others will want a lot more and setting it to 20 will probably inherit most every valid trait possible from the parents combined with a 'Inherit Maximum Number' setting of Inherit Trait Type. There just isn't a super large number of traits that are valid for babies and aren't specifically used for other things in gameplay (gender, age, hidden, personality and occult traits).","MenuPath":"MCCC > MC Pregnancy > Offspring > Maximum Inherit Traits","DefaultValue":"2","Module":"MC Pregnancy"},{"SettingName":"Population_HomelessApartmentPercent","Description":"When moving Sims in homeless households to populate empty apartments, this percentage will be checked to determine whether to allow the move to happen or not. Only apartments with at least one bed in the Lot info will be valid for move-in.","MenuPath":"MCCC > MC Population > Moving Settings > Homeless Apartment Percent","DefaultValue":"100","Module":"MC Population"},{"SettingName":"Pregnancy_SameSexPercentage","Description":"This setting will be used during partner selection if both Sims being tested have the same gender. In that case, a random roll against the percentage will be made to determine whether to allow that pregnancy. This setting is only used if same sex pregnancies are already determined to be valid based on 'Male Pregnancy' and 'Partner Gender' settings. Note that if the random percentage determines to not allow same-sex partners for a specific target Sim, that same Sim will be bypassed for all same-sex pregnancies for the current pregnancy cycle.","MenuPath":"MCCC > MC Pregnancy > Partner Sim Selection > Same Sex Percentage","DefaultValue":"50","Module":"MC Pregnancy"},{"SettingName":"Marriage_SameSexPercentage","Description":"This setting will be used during spouse selection if both Sims being tested have the same gender. In that case, a random roll against the percentage will be made to determine whether to allow that marriage. The 'Spouse Gender' settings have to allow same sex marriages to occur through the random process. Note that if the random percentage determines to not allow same-sex partners for a specific target Sim, that same Sim will be bypassed for all same-sex marriages for the current marriage cycle.","MenuPath":"MCCC > MC Pregnancy > Spouse Sim Selection > Same Sex Percentage","DefaultValue":"50","Module":"MC Marriage"},{"SettingName":"Tuner_DisableWitnessDeath","Description":"If enabled, the 'witness death' interaction that is pushed on Sims nearby when a Sim dies will not happen. This does not disable the sadness moodlet that Sims get when someone they know dies. It just disables the interruption to whatever they were doing to run over and watch the death happen.","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior > Disable Witness Death","DefaultValue":"False","Module":"MC Tuner"},{"SettingName":"Bypass_Sim_Menus","Description":"This setting allows the player to choose menus to not show (bypass) on the Sim MCCC menu. Note that this only affects the menu displayed when you click a Sim and go into the 'MC Command Center' menu. It does not affect the 'mccc' console command menu, so all menu options will always be available from the console menu.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Show Menu Settings > Bypass Specific Menus","DefaultValue":"''","Module":"MC Command Center"},{"SettingName":"Population_RandomUseTraySimPercent","Description":"Determines the chance that a Sim randomly generated by the Sims 4 will import the name and appearance of a Sim from the library of the player instead. 100% means only tray Sims will be used. 0% means no tray Sims will be used.","MenuPath":"MCCC > MC Population > Populating Settings > Import Tray Settings > Import Tray Sim Percent","DefaultValue":"0","Module":"MC Population"},{"SettingName":"Population_RandomLimitHouseholdType","Description":"When importing a Sim from the library, this setting will limit the households used for import to only player, only others (from online) or any saved Sims. The default is 'Any Saved Sims'.","MenuPath":"MCCC > MC Population > Populating Settings > Import Tray Settings > Import Tray Sim Type","DefaultValue":"'A'","Module":"MC Population"},{"SettingName":"Population_RandomUseTrayGenderSet","Description":"When importing a Sim from the libary, include any gender options saved on the imported Sim. Defaults to True.","MenuPath":"MCCC > MC Population > Populating Settings > Import Tray Settings > Include Gender Options","DefaultValue":"True","Module":"MC Population"},{"SettingName":"Population_RandomUseTrayOutfits","Description":"If enabled, when the Sim being imported the clothing from the imported Sim will also be included.","MenuPath":"MCCC > MC Population > Populating Settings > Import Tray Settings > Include Clothing","DefaultValue":"False","Module":"MC Population"},{"SettingName":"Use_Random_Aging","Description":"This setting determines whether EA's new random aging that was implemented with Get Famous will be used. If disabled, then the prior Sims 4 functionality will be used so new Sims are always zero days into their current age span rather than a random number of days.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Use Random Aging","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Pregnancy_PauseSimsPregnancy","Description":"This setting allows selection of groups of Sims who will not have their pregnancy progress as long as the setting is set. The setting can contain multiple values including 'Active Sims', 'Played Sims' and 'NPC Sims'. If all 3 are selected, all pregnant Sims in the game will have their pregnancy paused. If none are selected, no pregnant Sims will have their pregnancy paused unless the player has used the 'Pause Pregnancy' MC Pregnancy command mentioned previously. This setting differs from the 'Pause Playable Labor' setting in that it immediately stops all progression of pregnancy unlike 'Pause Playable Labor'. The 'Pause Playable Labor' setting continues pregnancy until it reaches the point of labor and then shows the player a dialog letting them know that it is time for the pregnant Sim to deliver.","MenuPath":"MCCC > MC Pregnancy > Other Pregnancy > Pause Sims Pregnancy","DefaultValue":"''","Module":"MC Pregnancy"},{"SettingName":"Population_UseTagsOnImportSims","Description":"This setting will allow filtering the households selected to replace randomly generated Sims by a tag in the description of the households. The default setting is 'Disabled' and will not read the description of the household from the gallery, which provides a little bit faster processing time at the cost of some flexibility of the player. Choosing 'Limit Bypass Tags' will not import a random Sim from a household with '#mccc_bypass' within the description. Choosing 'Only Include Tags' will bypass any household that does not include '#mccc_include' in the description when replacing a random Sim. Households for either setting will still show-up on copy/paste import Sim menus since the player has a choice on those menus. The player has to manually select households and Sims from that menu before they will be pasted into the game.","MenuPath":"MCCC > MC Population > Populating Settings > Import Tray Settings > Limit Import By Tags","DefaultValue":"''","Module":"MC Population"},{"SettingName":"Club_ClubMemberCount","Description":"Changing this from the default of 8 to a maximum of 50 changes the number of Sims that can become members in a club. Note that the EA Club Dialog UI is hard-coded to only show the '+' for Sims up-to-8 Sims. After that, Sims can still be added to clubs through invite interactions up to the maximum count selected. Also, the clubs should have the two extra slot perks purchased before this will work. The club has to be at the maximum of 8 before it can go higher...","MenuPath":"MCCC > MC Clubs > Club Member Count","DefaultValue":"8","Module":"MC Clubs"},{"SettingName":"Pregnancy_UseGenderPreference","Description":"This setting will use the target Sim's gender preferences when determining if they should become pregnant with another Sim. This is an additional check to any other MC Pregnancy settings that may be involved.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Use Gender Preference","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Marriage_UseGenderPreference","Description":"This setting will use the target Sim's gender preferences when determining if they should marry another Sim. This is an additional check to any other MC Marriage settings that may be involved.","MenuPath":"MCCC > MC Pregnancy > Marriage Sim Selection > Use Gender Preference","DefaultValue":"False","Module":"MC Marriage"},{"SettingName":"Decay_Ratio_Fame","Description":"Allows changing the decay rate of the Fame of a Celebrity Sim. 100, which is the default, results in normal fame decay. Below 100 reduces the rate at which fame decays. 50 = half the normal decay rate. 0 = no decay. etc. Going above 100 (up to 500) increases the rate at which fame decays making it drop up-to 2x faster than default EA levels. Traits and buffs that affect Motive decay will still apply to the new decay rate as well unless it's set to zero.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Motive Decay > Fame Decay Percent","DefaultValue":"100","Module":"MC Command Center"},{"SettingName":"Pregnancy_UseRandomMoods","Description":"If enabled, Sims will get random mood buffs during their pregnancy. Note that if they already have a pregnancy buff like for morning sickness, they will not get an additional random mood buff.","MenuPath":"MCCC > MC Pregnancy > Other Pregnancy > Use Random Moods","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_RandomMoodDuration","Description":"This setting determines how often a new random pregnancy buff will be added to the pregnant Sim as well as how long the buffs will last in Sim hours.","MenuPath":"MCCC > MC Pregnancy > Other Pregnancy > Random Mood Duration","DefaultValue":"1","Module":"MC Pregnancy"},{"SettingName":"CAS_AutoCelebrityWalkstyle","Description":"If this setting is enabled, when a Sim levels-up to rank 4 of Celebrity, they will automatically start walking with the celebrity walkstyle. If it is disabled, Sims do not automatically start using the celebrity walkstyle. It can be turned on-and-off as normal, though, on the Sim. Note that when a Sim goes to a celebrity event, the event itself may toggle on the celebrity walk if the Sim is rank 4 or above.","MenuPath":"MCCC > MC CAS > Walkstyle Settings > Auto-Set Celebrity Walkstyle","DefaultValue":"True","Module":"MC CAS"},{"SettingName":"Population_ImportSimNameChoice","Description":"Import Sims differently if a Sim in the world already has the name of the Sim from the import tray: Skip Sim if Name Exists - This is the default implementation and the way importing Sims has worked up to this release. If a Sim already exists in the world with the same name as the Sim being checked for import from the tray, then that Sim is not imported. This is the only setting that will prevent the same version of a Sim from existing in the world, which is why it was the implemented process I always followed before. Always Use Import Name - Regardless of whether a Sim already exists or not in the world with the same name, the Sim is imported from the tray replacing the random Sim's name with the import Sim's name. This can result in the same Sim being imported multiple times in the world with the same name. Use Non-Duplicate Name - If the Sim already exists in the world with the same name, the imported name is not used. The Sim is still imported, they are just left with the randomly generated Sim's name rather than the name from the import tray Sim. Can also result in the same Sim being imported multiple times in the world, but they will have different names with this setting. Never Use Import Name - Regardless of whether a Sim already exists or not in the world with the same name, the Sim is imported from the tray using the random Sim's name. This can result in the same Sim being imported multiple times in the world but they will have different names. The only difference between this setting and 'Use Non-Duplicate Name' is that the first time a Sim is imported, their name will be placed on the target Sim with 'Use Non-Duplicate Name'. With 'Never Use Import Name', the Sims will always use the randomly generated Sim name.","MenuPath":"MCCC > MC Population > Populating Settings > Import Tray Settings > Import Sim Name","DefaultValue":"N","Module":"MC Population"},{"SettingName":"Pregnancy_AgeUpDaysLimit","Description":"This setting prevents a Sim from becoming pregnant through random NPC pregnancy checks if they are within the specified number of days until they reach the end of the oldest age span available in the Age To Run Pregnancy setting. So, for example, if a Sim is a Young Adult and Young Adult, Adult and Elder ages are selected as valid ages for 'Age to Run Pregnancy' in MC Pregnancy, then by default they can become pregnant in any of those ages. However, if this setting is set to 10, then they would only become pregnant if they were within 10 days of reaching the end of the Elder age span, since it is the oldest age in their specified 'Age to Run' age spans. Depending on a person's age durations and gaming speed settings in Game Options, 10 days could make it valid for them to be pregnant through Young Adult and Adult and partially into the Elder age span. As long as there are 10 days left until they reach the end of the Elder age-span and die, basically.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Days Until Max Age","DefaultValue":"0","Module":"MC Pregnancy"},{"SettingName":"Career_Difficulty_Adjustment","Description":"This setting Increases/decreases the speed of Career progression. Valid settings are from -50 to 10 with a default of zero. Negative is slower progress, positive is faster. Every negative point is -10%, so -10 is 100% slower, -20 is 200% slower, etc. Positive are 100% per point, so 2 is 200% faster up to 10 which is 1000% faster.","MenuPath":"MCCC > MC Career > Career Difficulty Adjustment","DefaultValue":"0","Module":"MC Career"},{"SettingName":"Pregnancy_SameOccultOnly","Description":"If enabled, this setting ensures that Sims will only become pregnant with Sims of the same Occult type. So aliens with other aliens (or hybrids), vampires with vampires and mermaids with mermaids.","MenuPath":"MCCC > MC Pregnancy > Partner Sim Selection > Same Occult Only","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Marriage_SameOccultOnly","Description":"If enabled, this setting ensures that Sims will only marry Sims of the same Occult type. So aliens with other aliens (or hybrids), vampires with vampires and mermaids with mermaids.","MenuPath":"MCCC > MC Pregnancy > Spouse Sim Selection > Same Occult Only","DefaultValue":"False","Module":"MC Marriage"},{"SettingName":"Logging_LessLENotes","Description":"If enabled, the first time a LE happens in the current zone, a notification will be shown. No other notifications will be shown until the player changes to another zone or does something else to trigger the current lot to reload. If disabled, a notification will be displayed everytime a Last Exception is logged by the Sims 4. Note that mc_cmd_center.log errors will still show for each error that occurs. This is only altering how LE's are handled. If players want the more detailed LE notifications, they should disable the setting manually.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Logging Settings > Less LE Notifications","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Show_HouseEmptyNotification","Description":"If enabled, when the last Sim in a household dies or moves out through in-game processes (not by a player moving them in Manage Households), a notification will be displayed that the household is empty.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Notification Settings > MC Population Notifications > Show Empty House Notifications","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Show_VersionCheckNotification","Description":"Allows a version check against Deaderpool's website to be made to determine if a newer version of MCCC should be in use. Options include: 'Never', which relies on the player manually checking for updates, 'When Game Updates' will check when the Sims 4 version is updated and 'Always' checks everytime a game is started. 'Never' is the default, because I know some players don't want a lot of external calls being made to servers and they'd rather manually handle their version updates. This is totally opt-in functionality.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Notification Settings > Show Version Update Notifications","DefaultValue":"'N'","Module":"MC Command Center"},{"SettingName":"BB_Show_Live_Objects","Description":"If enabled, the ShowLiveObjects cheat (bb.showliveeditobjects) will always be enabled upon loading the game. Note that the bb.showhiddenobjects command is always automatically run for this setting, as well, as it is needed for it to work correctly.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Console Command Settings > Build/Buy Settings > ShowLive Enabled","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Pregnancy_AllowAffairsPercent","Description":"Percentage chance to allow married Sims to be parents in random pregnancies outside of their marriage. Zero will result in no affairs. 100 will result in only affairs (why?)","MenuPath":"MCCC > MC Pregnancy > Partner Sim Selection > Allow Affairs Percentage","DefaultValue":"0","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_TargetSimAges","Description":"Specifies the ages that Sims must be for eligibility for pregnancy. One or more ages may be chosen. Note that Teens will only be available for this setting if the MC Woohoo module is deployed.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Valid Target Ages","DefaultValue":"'A' for Adult","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_SeedSimAges","Description":"Specifies the ages that Sims must be for eligibility to be partners for pregnancy. One or more ages may be chosen. Note that Teens will only be available for this setting if the MC Woohoo module is deployed.","MenuPath":"MCCC > MC Pregnancy > Partner Sim Selection > Valid Partner Ages","DefaultValue":"'A' for Adult","Module":"MC Pregnancy"},{"SettingName":"Marriage_TargetSimAges","Description":"Specifies the ages that Sims must be for eligibility for marriage. One or more ages may be chosen. Note that Teens will only be available for this setting if the MC Woohoo module is deployed.","MenuPath":"MCCC > MC Pregnancy > Marriage Sim Selection > Valid Marriage Ages","DefaultValue":"'A' for Adult","Module":"MC Marriage"},{"SettingName":"Marriage_SpouseSimAges","Description":"Specifies the ages that Sims must be for eligibility to be spouses for marriage. One or more ages may be chosen. Note that Teens will only be available for this setting if the MC Woohoo module is deployed.","MenuPath":"MCCC > MC Pregnancy > Spouse Sim Selection > Valid Spouse Ages","DefaultValue":"'A' for Adult.","Module":"MC Marriage"},{"SettingName":"Inherit_Sim_Type","Description":"This setting will determine what type of Sims will leave money for their spouse or children when they die. The options are 'None', 'NPC Only', 'Played Only', 'Played and NPC Only', 'Active Only' and 'All' with the default being 'None'. If a Sim dies that matches the Sim type specified in this setting, then a portion of their household funds (if there are multiple adults in the household, then a portion of the household funds still belong to them so it should not be passed along) will be either given to their spouse, or divided among their children. If their children do not live with them currently, then their households will be increased based on a share of the total inheritance amount (divided equally among all children).","MenuPath":"MCCC > MCCC Settings > Money Settings > Inheritance Sim Type","DefaultValue":"'0'","Module":"MC Command Center"},{"SettingName":"Inherit_Spouse_First","Description":"If this setting is enabled, a spouse will inherit a dying Sim's portion of the household funds rather than it be divided among the children. Note that the spouse must be alive, not in a hidden household or a special Sim (Grim Reaper or some such thing).","MenuPath":"MCCC > MCCC Settings > Money Settings > Inheritance Spouse First","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Population_ImportBypassAppearance","Description":"If enabled, when a Sim is imported from the tray to replace a randomly generated Sim, it will automatically flag that Sim with the 'Flag Freeze Physique' and 'Flag Freeze Appearance'.","MenuPath":"MCCC > MC Population > Populating Settings > Import Tray Settings > Import Bypass Appearance","DefaultValue":"False","Module":"MC Population"},{"SettingName":"Occult_CustomPregnancyAlienHybrid","Description":"The chance alien and hybrid parents will have alien or hybrid babies per delivery. Defaults to 100 for aliens as MC Occult will default for Alien and Hybrid parents to always have alien children unless changes are made to the settings. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Aliens > Other Pregnancy > Custom Percentages > Alien and Hybrid","DefaultValue":"0,100,-1,-1,-1,-1","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyHybridHybrid","Description":"The chance hybrid and hybrid parents will have alien or hybrid babies per delivery. Defaults to 100 for hybrids as MC Occult will default for hybrid parents to always have hybrid children unless changes are made to the settings. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Aliens > Other Pregnancy > Custom Percentages > Hybrid","DefaultValue":"0,100,-1,-1,-1,-1","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyAlienHuman","Description":"The chance alien and human parents will have alien or hybrid babies per delivery. Defaults to 100 for hybrids as MC Occult will default for alien and human parents to always have hybrid children unless changes are made to the settings. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Aliens > Other Pregnancy > Custom Percentages > Alien and Human","DefaultValue":"0,100,-1,-1,-1,-1","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyHybridHuman","Description":"The chance hybrid and human parents will have alien or hybrid babies per delivery. Defaults to 100 for hybrids as MC Occult will default for hybrid and human parents to always have hybrid children unless changes are made to the settings. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Aliens > Other Pregnancy > Custom Percentages > Hybrid and Human","DefaultValue":"0,100,-1,-1,-1,-1","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyVampireHuman","Description":"The chance vampire and human parents will have vampire babies per delivery. Defaults to 50 for vampire babies. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Vampires > Other Pregnancy > Custom Percentages > Vampire and Human","DefaultValue":"-1,-1,50,-1,-1,-1","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyVampireAlien","Description":"The chance vampire and alien parents will have alien, hybrid or vampire babies per delivery. Defaults to zero for all as MC Occult will default for vampire and alien parents to always have human children unless changes are made to the settings. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Vampires > Other Pregnancy > Custom Percentages > Vampire and Alien","DefaultValue":"0,0,0,-1,-1,-1","Module":"MC Occult"},{"SettingName":"Occult_MaximumMermaids","Description":"Sets a maximum number of desired mermaids for the world. If the number of current mermaids in the world is greater than or equal to this number then no more mermaid babies will be BORN. This does not change homeless mermaids that the game generates, it only will prevent babies from being born as mermaids.","MenuPath":"MCCC > MC Occult > Mermaids > Maximum Mermaids","DefaultValue":"-1 = No limit","Module":"MC Occult"},{"SettingName":"Occult_ForceMermaidForm","Description":"If this setting is enabled, when placing mermaid Sims on lots, they will initially always be in their mermaid form, even if they are not in water. This can change if an EA-situation happens to change them back but initially, they will always be in mermaid form.","MenuPath":"MCCC > MC Occult > Mermaids > Force Mermaid Form","DefaultValue":"False","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyMermaidHuman","Description":"The chance mermaid and human parents will have mermaid babies per delivery. Defaults to 50 for mermaids. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Mermaids > Other Pregnancy > Custom Percentages > Mermaid and Human","DefaultValue":"-1,-1,-1,50,-1,-1","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyMermaidAlien","Description":"The chance mermaid and alien parents will have mermaid, alien or hybrid babies per delivery. Defaults to 50 for mermaid babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Mermaids > Other Pregnancy > Custom Percentages > Mermaid and Alien","DefaultValue":"0,0,-1,50,-1,-1","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyMermaidVampire","Description":"The chance mermaid and vampire parents will have mermaid or vampire babies per delivery. Defaults to 50 for mermaid babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Mermaids > Other Pregnancy > Custom Percentages > Mermaid and Vampire","DefaultValue":"-1,-1,0,50,-1,-1","Module":"MC Occult"},{"SettingName":"Dresser_SituationUseStandardOutfits","Description":"If enabled, when a situation tries to generate a random outfit of a specific category (like Athletic), it will instead use one of the outfits already saved on the Sim for that category. This is different than 'Replace Situation Outfits' as that setting allows replacing a situation-specific randomly generated outfit with a specific outfit category.","MenuPath":"MCCC > MC Dresser > Situation Use Standard","DefaultValue":"False","Module":"MC Dresser"},{"SettingName":"Occult_MaximumSpellcasters","Description":"Sets a maximum number of desired spellcasters for the world. If the number of current spellcasters in the world is greater than or equal to this number then no more spellcaster babies will be BORN. This does not change homeless spellcasters that the game generates, it only will prevent babies from being born as spellcasters.","MenuPath":"MCCC > MC Occult > Spellcasters > Maximum Spellcasters","DefaultValue":"-1 = No Limit","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyWitchAlien","Description":"The chance spellcaster and alien parents will have spellcaster, alien or hybrid babies per delivery. Defaults to 50 for spellcaster babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Spellcasters > Other Pregnancy > Custom Percentages > Spellcaster and Alien","DefaultValue":"0,0,-1,-1,50,-1","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyWitchVampire","Description":"The chance spellcaster and vampire parents will have spellcaster or vampire babies per delivery. Defaults to 50 for spellcaster babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Spellcasters > Other Pregnancy > Custom Percentages > Spellcaster and Vampire","DefaultValue":"-1,-1,0,-1,50,-1","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyWitchMermaid","Description":"The chance spellcaster and mermaid parents will have spellcaster or mermaid babies per delivery. Defaults to 50 for spellcaster babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Spellcasters > Other Pregnancy > Custom Percentages > Spellcaster and Mermaid","DefaultValue":"-1,-1,-1,0,50,-1","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyWitchHuman","Description":"The chance spellcaster and human parents will have spellcaster babies per delivery. Defaults to 50 for spellcaster babies. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Spellcasters > Other Pregnancy > Custom Percentages > Spellcaster and Human","DefaultValue":"-1,-1,-1,-1,50,-1","Module":"MC Occult"},{"SettingName":"Teleport_Sim_Overlap","Description":"If this is enabled, when Sims are teleported to other Sims, they will appear right on top of them. This may be preferred by people using posing mods to do screenshots. If that is not the desired behavior and it would be preferred that the teleported Sim arrives to the side of the target Sim, disabling this setting will provide that functionality. Note that this setting doesn't require a restart to change so the behaviors can be changed as needed for screenshots or not without restarting the game.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Teleport Sim Overlap","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Put_Away_Books_Fix","Description":"If enabled, Teens will put homework in their inventory when they complete it.","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior","DefaultValue":"True","Module":"MC Tuner"},{"SettingName":"Show_Gnome_Menu_Type","Description":"Settings include 'A' - always ('All Menus'), 'ASH' - enabled only when holding Shift ('All with Shift Key') or 'N' - not be shown at all ('None'). Since this is a pretty limited-use menu, the default will be 'None' so it doesn't show at all. It will have to be changed to be enabled.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Show Menu Settings > Show Gnome Menu","DefaultValue":"N","Module":"MC Command Center"},{"SettingName":"Maximum_Rename_Length","Description":"This setting determines the maximum length allowed for First and Last Name each when renaming a Sim with MCCC. Default is 14. WARNING: Specifying a first or last name longer than 14 characters will result in a CAS error if that Sim is modified and saved. If you don't go into CAS, you'll be fine, but this is why I don't allow more than 14 by default.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Maximum Rename Length","DefaultValue":"14","Module":"MC Command Center"},{"SettingName":"Bypass_Dorm_Residents","Description":"When enabled, this setting will prevent elderly dorm residents from being moved into retirement homes or single Sims from moving out of dorms due to the settings in MC Population. It also prevents dorm residents from being able to be marked as homeless.","MenuPath":"MCCC > MC Population > Moving Settings > Bypass Dorm Residents","DefaultValue":"True","Module":"MC Population"},{"SettingName":"Dresser_CopyPasteFacepaint","Description":"If enabled, copy/pasting makeup will also copy/paste facepaint. Since some CC (like contact lenses) may use the facepaint slot, this will allow copying those type of items as well if desired.","MenuPath":"MCCC > MC Dresser > Makeup Settings > Copy/Paste Facepaint","DefaultValue":"False","Module":"MC Dresser"},{"SettingName":"Pregnancy_BypassRobots","Description":"If this is enabled, then robots will not be either the target or the partner for random pregnancies.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Bypass Robots","DefaultValue":"True","Module":"MC Pregnancy"},{"SettingName":"Career_University_Difficulty_Adjustment","Description":"This setting Increases/decreases the speed of University progression. Valid settings are from -50 to 10 with a default of zero. Negative is slower progress, positive is faster. Every negative point is -10%, so -10 is 100% slower, -20 is 200% slower, etc. Positive are 100% per point, so 2 is 200% faster up to 10 which is 1000% faster.","MenuPath":"MCCC > MC Career > University Difficulty Adjustment","DefaultValue":"0","Module":"MC Career"},{"SettingName":"Cleaner_DetailLogging","Description":"If enabled, when MC Cleaner runs on scheduled nights, a higher level of detail will be displayed on what cleaning was specifically done. Note that increased logging may cause performance hits when the cleaning processes are running. Any output to files can have that effect and logging is no different.","MenuPath":"MCCC > MC Cleaner > Detail Logging","DefaultValue":"False","Module":"MC Cleaner"},{"SettingName":"Population_ButlerAges","Description":"Previously, EA only allowed Adult and Elder butlers, but this setting will expand it to allow Teen and Young Adult Sims as well.","MenuPath":"MCCC > MC Population > Populating Settings... > Butler Age","DefaultValue":"Adult,Elder","Module":"MC Population"},{"SettingName":"CAS_Trait_Blacklist","Description":"Add personality traits that are not desired to an exclude list. Excluded traits only apply to randomly generated Sims or Sims that are aging-up and gaining new traits. It does not apply retroactively to existing Sims in the world who already have the excluded traits. It also will not apply to Sims created through Testing/Debug Cheats to generate a Sim. If a Sim is imported from the player's library, it also will not apply as imported Sims will include the traits they were saved with. Excluded traits will not be removed from Sims filling roles that require the excluded trait for their role.","MenuPath":"MCCC > MC CAS > Exclude Traits > Personality Traits","DefaultValue":"''","Module":"MC CAS"},{"SettingName":"CAS_Pet_Trait_Blacklist","Description":"Add personality traits that are not desired to an exclude list. Excluded traits only apply to randomly generated Pets or Pets that are aging-up and gaining new traits. It does not apply retroactively to existing Pets in the world who already have the excluded traits. It also will not apply to Pets created through Testing/Debug Cheats to generate a Pet. Excluded traits will not be removed from Pets filling roles that require the excluded trait for their role.","MenuPath":"MCCC > MC CAS > Exclude Traits > Exclude Pet Traits","DefaultValue":"''","Module":"MC CAS"},{"SettingName":"Dresser_FacialHairAges","Description":"These are the ages that will be tested when the Sim ages into that age, if they should have facial hair added. Any combination of Teen, Young Adult, Adult and Elder are supported. Note that if a Sim already has facial hair, nothing in this new process will remove the existing facial hair. It is just an option to add facial hair if they don't already have it. Also, players must have added hair to the MC Dresser Include List for their males in that age group for a hair to be added. There's no way to force CAS to generate facial hair from script so the Include List gives us options to use if CAS doesn't generate the facial hair by default.","MenuPath":"MCCC > MC Dresser > Facial Hair Settings... > Facial Hair Ages","DefaultValue":"Young Adult","Module":"MC Dresser"},{"SettingName":"Dresser_FacialHairPercent","Description":"The percentage chance, at each age, that facial hair will be added when the Sim ages to that age.","MenuPath":"MCCC > MC Dresser > Facial Hair Settings... > Facial Hair Percents","DefaultValue":"0,0,0,0","Module":"MC Dresser"},{"SettingName":"Pregnancy_RelationshipOnly","Description":"'No Relationship Limit', the default, is standard MC Pregnancy behavior. Any two Sims are valid for pregnancy together as long as they match the other MC Pregnancy setting criteria. 'Married Only' - only married Sims will become pregnant, 'Significant Others' - allows pregnancy between Sims only if they're significant others, 'Woohoo Partners' - allows pregnancy if the two Sims have ever had woohoo in the past. Each setting is a bit more inclusive than the previous. Significant Others includes married but also other significant others. Woohoo includes Married and Significant others but also any other Sims that have woohooed.","MenuPath":"MCCC > MC Pregnancy > Partner Sim Selection > Limit By Relationship","DefaultValue":"N","Module":"MC Pregnancy"},{"SettingName":"Tuner_AutoGarden","Description":"If enabled, any Sim Teen-or-older on a lot may garden something that needs tending.","MenuPath":"MCCC > MC Tuner > Change Interaction Autonomy > Autonomous Gardening","DefaultValue":"false","Module":"MC Tuner"},{"SettingName":"Woohoo_NudeInShower","Description":"Determines whether Sims defined in Woohoo_NudeWoohooGender and Woohoo_NudityAges will become nude for shower woohoo.","MenuPath":"MCCC > MC Woohoo > Sim Nudity > Nudity Interactions > Nude Shower Woohoo","DefaultValue":"false","Module":"MC Woohoo"},{"SettingName":"Population_MoveTeenDependent","Description":"This setting determines if teen Sims are treated as dependents or if they are allowed to move out into a single household by themselves. Additionally, if they are dependents, when their parents move due to pregnancy/marriage and the “Move Families” setting is enabled in MC Pregnancy, they will move with the family. Defaults to True. Note that this does not affect teens moving if they get married themselves. If that is allowed in MC Pregnancy/Marriage settings, then they are allowed to move as they always have.","MenuPath":"MCCC > MC Population > Move Settings > Move Teens as Dependents","DefaultValue":"True","Module":"MC Population"},{"SettingName":"Friendship_Difficulty_Adjustment","Description":"This setting will make Friendship relationships take more or less time to build. Valid settings are from -50 to 10 with a default of zero. Negative is slower progress, positive is faster. Every negative point is -10%, so -20 is 200% slower, -30 is 300% slower, etc. Positive are 100% per point, so 2 is 200% faster up to 10 which is 1000% faster.","MenuPath":"MCCC > Relationship Settings > Friendship Difficulty Adjustment","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Romance_Difficulty_Adjustment","Description":"This setting will make Friendship relationships take more or less time to build. Valid settings are from -50 to 10 with a default of zero. Negative is slower progress, positive is faster. Every negative point is -10%, so -20 is 200% slower, -30 is 300% slower, etc. Positive are 100% per point, so 2 is 200% faster up to 10 which is 1000% faster.","MenuPath":"MCCC > Relationship Settings > Romance Difficulty Adjustment","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Tuner_InstantUpgrade","Description":"When enabled, Sims will perform upgrades instantly and will require no components. Note that all of the upgrade interactions have a bit of an animation that goes with them that plays before the upgrade instantly finishes. So it's not instant-instant, but it is instant as soon as the upgrade begins in code!","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior > Allow Instant Upgrades","DefaultValue":"False","Module":"MC Tuner"},{"SettingName":"Skill_Cheats_Bypass","Description":"Any MC Cheat command that alters all skills, like 'Forget All Skills' or 'Max All Skills' or 'Randomize Skill Levels', will not run on Skills within this list. The skill list shown will be based on the currently selected Sim.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Skill Settings > Bypass Skill List","DefaultValue":"''","Module":"MC Command Center"},{"SettingName":"Woohoo_UseBirthControl","Description":"If this setting is enabled, the birth control interaction will be available. If it's disabled, the interaction will never show-up for Sims.","MenuPath":"MCCC > MC Woohoo > Other Settings > Allow Birth Control","DefaultValue":"true","Module":"MC Woohoo"},{"SettingName":"Appearance_UseParentFacialDetails","Description":"If enabled, parent's facial skin details may be passed along to their children. Because babies/toddlers and Children use different internal ID's for skin details, those can't be copied over from parents. This setting will work like 'Use Parent Physical Attributes', which happens when the offspring age-up to Teen. At that point, the internal ID's match between the offspring and the parents so they can be copied. If both parents have the same facial attribute but different types (different freckles, for example), then it's a 50/50 chance which one the child will inherit.","MenuPath":"MCCC > MC CAS > Offspring > Use Parent Skin Details","DefaultValue":"false","Module":"MC CAS"},{"SettingName":"Population_MaximumHouseholdPets","Description":"This setting will determine the maximum number of pets that can be adopted by households, if any, during random move-ins. The default is zero, which is no automatic stray move-in. The maximum value this setting allows is 103, which is one less than the maximum household size that can be set, and players can use -1 as unlimited if a they just want it be unlimited without having to set it to a specific number.","MenuPath":"MCCC > MC Population > Moving Settings > Maximum Household Pets","DefaultValue":"0","Module":"MC Population"},{"SettingName":"Tuner_Child_Pay_Bills","Description":"If enabled, then a child can pay bills on mailboxes, phones, tablets and computers.","MenuPath":"MCCC > MCCC Settings > Money Settings > Allow Child Pay Bills","DefaultValue":"False","Module":"MC Tuner"},{"SettingName":"Tuner_Child_Baby_Care","Description":"When enabled, a child can perform basic baby and infant care interactions like bottle feeding, diaper changing, etc. Note that the animations for it might be a little 'off' since the interactions are made for teens/adults and not children.","MenuPath":"MCCC > MC Tuner > Change Interaction Behavior > Allow Child Baby Care","DefaultValue":"False","Module":"MC Tuner"},{"SettingName":"Skill_Difficulty_Whitelist","Description":"If this setting is set to a skill or list of skills, then only those skills will be adjusted by the Skill Difficulty Adjustment amount. The skill list shown will be based on the currently selected Sim.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Skill Settings > Skill Adjustment Whitelist","DefaultValue":"''","Module":"MC Command Center"},{"SettingName":"Skill_Difficulty_Blacklist","Description":"If this setting is set to a skill or a list of skills, then all skills EXCEPT the excluded skills will be adjusted by the Skill Difficulty Adjustment amount. The skill list shown will be based on the currently selected Sim.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Skill Settings > Skill Difficulty Exclude List","DefaultValue":"''","Module":"MC Command Center"},{"SettingName":"Career_Homework_Speed","Description":"Change school homework progression to be slower or faster. Valid settings are from -3 to 50 with a default of zero. Negative is slower progress, positive is faster. Every negative point is -100%, so -1 is 100% slower, -2 is 200% slower, etc. 10 is about 1/4 the normal homework speed. This affects child/teen homework, extra credit and makeup homework.","MenuPath":"MCCC > MC Careers > School Homework Progression","DefaultValue":"0","Module":"MC Career"},{"SettingName":"Career_University_Homework_Speed","Description":"Change university homework progression to be slower or faster. Valid settings are from -3 to 50 with a default of zero. Negative is slower progress, positive is faster. Every negative point is -100%, so -1 is 100% slower, -2 is 200% slower, etc. 10 is about 1/4 the normal homework speed. This affects university homework and term presentation.","MenuPath":"MCCC > MC Careers > University Homework Progression","DefaultValue":"0","Module":"MC Career"},{"SettingName":"LifeSkill_Difficulty_Adjustment","Description":"This setting Increases/decreases the speed of Life Skill progression. Valid settings are from -50 to 10 with a default of zero. Negative is slower progress, positive is faster. Every negative point is -10%, so -10 is 100% slower, -20 is 200% slower, etc. Positive are 100% per point, so 2 is 200% faster up to 10 which is 1000% faster.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Character Values Difficulty Adjustment","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Show_ClubMonitorNotifications","Description":"If enabled, MCCC will display a notification post when a Sim is added to a club that needs more members.","MenuPath":"MCCC Settings > Notification/Console/Menu Settings > Notification Settings > Show Club Monitor Notifications","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Menu_Order","Description":"Allows players to choose the order they want to use for the main Sim menu Note that all buttons show-up in the configuration dialog. On the actual Sim menu, some buttons may not show-up based on different factors, but in the reorder dialog, they will all be there. After the order has been changed as desired, going back to the previous dialog and choosing 'Save Current Order' will save that order into the settings as the new order for the main Sim menu. If you want to cancel, you just don't click the 'Save Current Order' button and it won't be saved to the settings. Once it's saved to the settings, it can't be cancelled. It can just be reset or manually changed back. The 'Reset to Default Order' button will just return all menu items to the MCCC default positions.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Change Sim Menu Order","DefaultValue":"Too long for details here","Module":"MC Command Center"},{"SettingName":"Relationship_MoveinPercent","Description":"The percentage chance that a move-in would happen between two qualified Sims, based on the other settings. If either Sim is already living with a significant other, then they will not move-out to live with a different Sim. If a Sim is already living with someone they're romantically involved with at the defined levels of the setting, then no other move-in would happen. If two Sims have been significant others in the past but have broken-up or divorced, they will not move-in together. If a Sim is homeless and another Sim lives on a lot, the Sim that lives on a lot will not move-in with the homeless Sim. If either Sim lives in a dorm, they won't move-in together. Sims that have children or are pregnant will not be valid to move-in with another Sim. Once they move-in together, they will be marked as significant others to prevent single-sim move-out from affecting them in that MC Population setting. Zero is disabled.","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Auto-Relationship Settings > Move-In Settings > Romance Move-In Percent","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Relationship_MoveinAges","Description":"This setting determines what ages are allowed to move-in together based on romance levels.","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Auto-Relationship Settings > Move-In Settings > Move-In Ages","DefaultValue":"Young Adult, Adult, Elders","Module":"MC Command Center"},{"SettingName":"Relationship_MoveinRomanceAmt","Description":"This setting determines at what romance level Sims must be at to move-in together. It includes 'Lovers' (25-49 romance), 'Sweethearts' (50-74), 'Soulmates' (75-99) and 'True Lovers' (100).","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Auto-Relationship Settings > Move-In Settings > Move-In Romance Level","DefaultValue":"50, which is the value for Sweethearts","Module":"MC Command Center"},{"SettingName":"Relationship_BypassPlayedHouseholds","Description":"Bypasses any household flagged as a 'Played Household' in the Manage Households screen so it will not be used for the Relationship break-up and move-in functions.","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Auto-Relationship Settings > Bypass Played Households","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Population_RandomChallengeMaxNum","Description":"The maximum number of challenges we want to randomly set on the current lot. Any number above zero will turn the feature on. This is the maximum number, but less than that may be set each time the challenges change. Also, some lots will have less challenges available and some will have more but it is ok if the maximum selected here is more than what is available for the current lot.","MenuPath":"MCCC > MC Population > Random Lot Challenges > Maximum Challenge Number","DefaultValue":"0","Module":"MC Population"},{"SettingName":"Population_RandomChallengeMaxTime","Description":"Defines how often we want the lot challenges to randomly change and is a number from 1 to 100.","MenuPath":"MCCC > MC Population > Random Lot Challenges > Maximum Challenge Frequency","DefaultValue":"7","Module":"MC Population"},{"SettingName":"Population_RandomChallengeTimeUnits","Description":"Defines what frequency type to use: Sim Hours or Sim Days. Something to keep in mind is that you probably want it long enough to actually have an affect on your lot. Some challenges are slower to show-up than others through normal game play.","MenuPath":"MCCC > MC Population > Random Lot Challenges > Challenge Unit Type","DefaultValue":"SD","Module":"MC Population"},{"SettingName":"Population_RandomChallengeLotType","Description":"This setting determines which type of lots will have random challenges applied. This setting limits it to only residential lots, only the active player's lot or all lots.","MenuPath":"MCCC > MC Population > Random Lot Challenges > Apply to Lot Type","DefaultValue":"A (Active Lot only)","Module":"MC Population"},{"SettingName":"Dresser_CleanBathingOutfit","Description":"Determines whether a bathing outfit is auto-cleaned (reset to only the EA default body parts) when MC Dresser is opened on a Sim wearing a bathing outfit. Some mods and cc allow setting outfit parts on the bathing outfit other than EA's defaults and players want to keep it so disabling this setting will allow that to happen.","MenuPath":"MCCC > MC Dresser > Automatically Clean Bathing Outfits","DefaultValue":"True","Module":"MC Dresser"},{"SettingName":"Skill_Freeze_List","Description":"Skills added to this list will be frozen and no longer improve.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Skill Settings > Skill Freeze Progression List","DefaultValue":"''","Module":"MC Command Center"},{"SettingName":"Marriage_SameNeighborhood","Description":"Control marrying Sims that live in the same neighborhood (world). Options include 'Always Limit Partners By Neighborhood' - will not allow Sims to be married, even if they're boyfriend/girlfriend/engaged if they don't live in the same neighborhood, 'Never Limit Partners By Neighborhood' - Ignore neighborhoods when marrying Sims, and 'Prefer Partners In Same Neighborhood' - Sims that are boyfriend/girlfriend/engaged will be married even if they're in different neighborhoods, but any other marriage partners have to be in the same neighborhood.","MenuPath":"MCCC > MC Pregnancy > Other Marriage > Same Neighborhood","DefaultValue":"'N'","Module":"MC Marriage"},{"SettingName":"Fame_Difficulty_Adjustment","Description":"This setting Increases/decreases the speed of Fame progression. Valid settings are from -50 to 10 with a default of zero. Negative is slower progress, positive is faster. Every negative point is -10%, so -10 is 100% slower, -20 is 200% slower, etc. Positive are 100% per point, so 2 is 200% faster up to 10 which is 1000% faster.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Fame Difficulty Adjustment","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Career_Decay_Ratio_SecretSociety","Description":"Modifying this setting will change the rate at which progress in the Secret Society Organization decays. 100 = normal. 0 = No progress decay. 200 = Double progress decay, etc.","MenuPath":"MCCC > MC Career > Secret Society Decay Percent","DefaultValue":"100","Module":"MC Career"},{"SettingName":"Population_PercentMaleFrame","Description":"Allows random chances for randomly generated female Sims to use a male physical frame.","MenuPath":"MCCC > MC Population > Populating Settings > CAS Custom Gender Settings > Percent Male Physical Frame","DefaultValue":"0","Module":"MC Population"},{"SettingName":"Population_PercentFemaleFrame","Description":"Allows random chances for randomly generated male Sims to use a female physical frame.","MenuPath":"MCCC > MC Population > Populating Settings > CAS Custom Gender Settings > Percent Female Physical Frame","DefaultValue":"0","Module":"MC Population"},{"SettingName":"Population_MatchCasToFrame","Description":"Determines whether or not to automatically have the clothing preferences, pregnancy options and toilet-use preferences set to match the new frame the Sim is using when using the 'Percent Male Physical Frame' or 'Percent Female Physical Frame' settings.","MenuPath":"MCCC > MC Population > Populating Settings > CAS Custom Gender Settings > Match CAS Settings To Frame","DefaultValue":"False","Module":"MC Population"},{"SettingName":"Pregnancy_LimitNS","Description":"When this is enabled, a Sim will only become pregnant through Neighborhood Stories if they are valid based on MC Pregnancy settings. A pregnant Sim's partner will similarly be limited to those defined by MC Pregnancy settings.","MenuPath":"MCCC > MC Pregnancy > Neighborhood Stories Settings > Alter Neighborhood Stories","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_OnlyNSPregnancy","Description":"When this is enabled, MC Pregnancy does not run random pregnancies on scheduled nights. The only pregnancies that happen are through Neighborhood Stories. If the 'Alter Neighborhood Stories' setting is enabled, then the NS pregnancies will still be limited by MC Pregnancy settings.","MenuPath":"MCCC > MC Pregnancy > Neighborhood Stories Settings > Only Use Neighborhood Stories","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Show_NSAdoptionType","Description":"Will display a notification post when a Sim gets adopted through Neighborhood stories based on whether they match this setting. The values include: '0'-No adoption notifications, 'N'-NPC's only, 'P'-Played/Active only, 'R'-Related to an active Sim only or 'AL'-All adoptions will show notifications.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Notification Settings > Neighborhood Stories Settings > Show Adoption Types","DefaultValue":"'0'","Module":"MC Command Center"},{"SettingName":"Show_NSPregnancyType","Description":"Will display a notification post when a Sim gets pregnant through Neighborhood stories based on whether they match this setting. The values include: '0'-No pregnancy notifications, 'N'-NPC's only, 'P'-Played/Active only, 'R'-Related to an active Sim only or 'AL'-All pregnancies will show notifications.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Notification Settings > Neighborhood Stories Settings > Show Pregnancy Types","DefaultValue":"'0'","Module":"MC Command Center"},{"SettingName":"Show_NSPetAdoption","Description":"If enabled, any Neighborhood Story that causes a Pet to be adopted by a household will trigger a notification about the adoption.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Notification Settings > Neighborhood Stories Settings > Show Pet Adoptions","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Show_NSPopulationType","Description":"Will display a notification post when a Sim changes residence through Neighborhood stories based on whether they match this setting. The values include: '0'-No notifications, 'N'-NPC's only, 'P'-Played/Active only, 'R'-Related to an active Sim only or 'AL'-All moving notifications.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Notification Settings > Neighborhood Stories Settings > Show Population Types","DefaultValue":"'0'","Module":"MC Command Center"},{"SettingName":"Show_NSCareerType","Description":"Will display a notification post when a Sim changes careers through Neighborhood stories based on whether they match this setting. The values include: '0'-No notifications, 'N'-NPC's only, 'P'-Played/Active only, 'R'-Related to an active Sim only or 'AL'-All career change notifications.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Notification Settings > Neighborhood Stories Settings > Show Career Types","DefaultValue":"'0'","Module":"MC Command Center"},{"SettingName":"Show_NSDeathType","Description":"Will display a notification post when a Sim has a random death due to a Neighborhood Story based on whether they match this setting. The values include: '0'-No notifications, 'N'-NPC's only, 'P'-Played/Active only, 'R'-Related to an active Sim only or 'AL'-All random death notifications.","MenuPath":"MCCC > MCCC Settings > Notification/Console/Menu Settings > Notification Settings > Neighborhood Stories Settings > Show Death Types","DefaultValue":"'0'","Module":"MC Command Center"},{"SettingName":"Population_LimitNS","Description":"When this is enabled, a Sim will not move onto a lot if they're flagged as homeless. A Sim will not move off a lot if their household is ancestral. Additionally, if the MC Population bypass played households setting is enabled then played households will not move in or off of lots.","MenuPath":"MCCC > MC Population > Neighborhood Stories Settings > Alter Neighborhood Stories","DefaultValue":"False","Module":"MC Population"},{"SettingName":"Occult_CustomPregnancyWerewolfHuman","Description":"This setting defines the percent chance werewolf and human parents will have werewolf babies per delivery. Defaults to 50 for werewolf. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Werewolves > Other Pregnancy > Custom Percentages > Werewolf and Human","DefaultValue":"-1,-1,-1,-1,-1,50","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyWerewolfAlien","Description":"This setting defines the percent chance werewolf and alien parents will have werewolf, alien or hybrid babies per delivery. Defaults to 50 for werewolf babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Werewolves > Other Pregnancy > Custom Percentages > Werewolf and Alien","DefaultValue":"0,0,-1,-1,-1,50","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyWerewolfVampire","Description":"This setting defines the percent chance werewolf and vampire parents will have werewolf or vampire babies per delivery. Defaults to 50 for werewolf babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Werewolves > Other Pregnancy > Custom Percentages > Werewolf and Vampire","DefaultValue":"-1,-1,0,-1,-1,50","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyWerewolfMermaid","Description":"This setting defines the percent chance werewolf and mermaid parents will have werewolf or mermaid babies per delivery. Defaults to 50 for werewolf babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Werewolves > Other Pregnancy > Custom Percentages > Werewolf and Mermaid","DefaultValue":"-1,-1,-1,0,-1,50","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyWerewolfWitch","Description":"This setting defines the percent chance werewolf and spellcaster parents will have werewolf or spellcaster babies per delivery. Defaults to 50 for werewolf babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Werewolves > Other Pregnancy > Custom Percentages > Werewolf and Spellcaster","DefaultValue":"-1,-1,-1,-1,0,50","Module":"MC Occult"},{"SettingName":"AgeSpanNormal","Description":"Specifies the number of days a human Sim will have in each age span for normal lifespans. Maximum is 4000.","MenuPath":"MCCC > MCCC Settings > Age Settings > Set Age Span Duration > Normal Lifespan > Human","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"AgeSpanShort","Description":"Specifies the number of days a human Sim will have in each age span for short lifespans. Maximum is 4000.","MenuPath":"MCCC > MCCC Settings > Age Settings > Set Age Span Duration > Short Lifespan > Human","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"AgeSpanLong","Description":"Specifies the number of days a human Sim will have in each age span for long lifespans. Maximum is 4000.","MenuPath":"MCCC > MCCC Settings > Age Settings > Set Age Span Duration > Long Lifespan > Human","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"AgeSpanCatNormal","Description":"Specifies the number of days a cat Sim will have in each age span for normal lifespans. Maximum is 1000.","MenuPath":"MCCC > MCCC Settings > Age Settings > Set Age Span Duration > Normal Lifespan > Cat","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"AgeSpanCatShort","Description":"Specifies the number of days a cat Sim will have in each age span for short lifespans. Maximum is 1000.","MenuPath":"MCCC > MCCC Settings > Age Settings > Set Age Span Duration > Short Lifespan > Cat","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"AgeSpanDogLong","Description":"Specifies the number of days a dog Sim will have in each age span for long lifespans. Maximum is 1000.","MenuPath":"MCCC > MCCC Settings > Age Settings > Set Age Span Duration > Long Lifespan > Dog","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"AgeSpanDogNormal","Description":"Specifies the number of days a dog Sim will have in each age span for normal lifespans. Maximum is 1000.","MenuPath":"MCCC > MCCC Settings > Age Settings > Set Age Span Duration > Normal Lifespan > Dog","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"AgeSpanDogShort","Description":"Specifies the number of days a dog Sim will have in each age span for short lifespans. Maximum is 1000.","MenuPath":"MCCC > MCCC Settings > Age Settings > Set Age Span Duration > Short Lifespan > Dog","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"AgeSpanCatLong","Description":"Specifies the number of days a cat Sim will have in each age span for long lifespans. Maximum is 1000.","MenuPath":"MCCC > MCCC Settings > Age Settings > Set Age Span Duration > Long Lifespan > Cat","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Adopt_No_Caregiver","Description":"Allow/disallow adoption of children Sims when death of all adults in the household occurs. This defaults to True because the default Sims 4 behavior is to delete the children Sims when no adults in the household remain.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Adopt No Caregiver","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Population_PercentInfant","Description":"The % chance a spawned homeless dependent Sim will be an Infant. Default age for dependents is Teen, which is used if infant, toddler, child or babies are not randomly selected.","MenuPath":"MCCC > MC Population > Populating Settings > Percent Infant","DefaultValue":"20","Module":"MC Population"},{"SettingName":"Woohoo_NudeInHotSprings","Description":"Determines whether Sims defined in Woohoo_NudeWoohooGender and Woohoo_NudityAges will become nude for Hot Springs woohoo.","MenuPath":"MCCC > MC Woohoo > Sim Nudity > Nudity Interactions > Nude Hot Springs Woohoo","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Club_MaximumClubCount","Description":"Sets the maximum number of clubs a Sim may join. Note that the Club dialog does not allow joining more than 3 clubs. The Sim will need to be invited through interactions or added through (MC Cheats > Cheat Sim Info > Expansion Cheats > Club Cheats).","MenuPath":"MCCC > MC Clubs > Maximum Joinable Clubs","DefaultValue":"3","Module":"MC Clubs"},{"SettingName":"Sims_Are_Immortal","Description":"Sims don't die.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Sims Are Immortal","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Cleaner_CleanPetRelationships","Description":"This setting stores the values necessary for MC Cleaner Pet relationship cleaning. The valid values are 'Z'-Zero Level only, 'C'-Custom Level (Any value between 0 and 100 may be specified), 'A'-acquaintances or less, 'F'-friends or less. Note that absolute values are used for the scores. So if a custom setting of 20 is set and the relationship score is between -20 and 20, then the relationship will be deleted.","MenuPath":"MCCC > MC Cleaner > Relationship Cleaner > Pet Relationship Cleaner","DefaultValue":"A","Module":"MC Cleaner"},{"SettingName":"MotiveDecay_Horses","Description":"Alters the rate at which the motives decay for Horses. 100, which is the default, results in normal motive decay. Below 100 reduces the rate at which motives decay. 50 = half the normal motive decay rate. 0 = no motive decay. etc. Going above 100 (up to 500) increases the rate at which motive decay making them drop 2x faster than default EA levels. Traits and buffs that affect Motive decay will still apply to the new decay rate as well unless it's set to zero.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Motive Decay > Horse Motive Decay Percent","DefaultValue":"100","Module":"MC Command Center"},{"SettingName":"Pregnancy_CatAgePercentage","Description":"The 'try for baby' percentage used when testing for random NPC cat pregnancies. It can be separately set for the Adult and Elder age groups. A number between 0 and 100 can be specified. 0 will turn-off random pregnancies for NPC cats.","MenuPath":"MCCC > MC Pregnancy > Pet Pregnancy Settings > Pregnancy Percentage > Cats","DefaultValue":"20% for all ages","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_DogAgePercentage","Description":"The 'try for baby' percentage used when testing for random NPC dog pregnancies. It can be separately set for the Adult and Elder age groups. A number between 0 and 100 can be specified. 0 will turn-off random pregnancies for NPC dogs.","MenuPath":"MCCC > MC Pregnancy > Pet Pregnancy Settings > Pregnancy Percentage > Dogs","DefaultValue":"20% for all ages","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_HorseAgePercentage","Description":"The 'try for baby' percentage used when testing for random NPC horse pregnancies. It can be separately set for the Adult and Elder age groups. A number between 0 and 100 can be specified. 0 will turn-off random pregnancies for NPC horses.","MenuPath":"MCCC > MC Pregnancy > Pet Pregnancy Settings > Pregnancy Percentage > Horses","DefaultValue":"20% for all ages","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_NSAdoptChildLimit","Description":"Limits Neighborhood Story adoptions to prevent unwanted repeated adoptions for the same household. It defines the maximum number of children that can already be in a household. The default of -1 allows Neighborhood Stories to trigger adoptions as normal. Any other number will not trigger an adoption if the number of children in the household is greater than the set value. Setting to zero will result in no child adoptions through Neighborhood Stories, even if there are no children currently in the household.","MenuPath":"MCCC > MC Pregnancy > Neighborhood Story Settings > Child Adoption Limit","DefaultValue":"-1","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_NSAdoptPetLimit","Description":"Limits Neighborhood Story adoptions to prevent unwanted repeated adoptions for the same household. It defines the maximum number of pets that can already be in a household. The default of -1 allows Neighborhood Stories to trigger adoptions as normal. Any other number will not trigger an adoption if the number of pets in the household is greater than the set value. Setting to zero will result in no pet adoptions through Neighborhood Stories, even if there are no pets currently in the household.","MenuPath":"MCCC > MC Pregnancy > Neighborhood Story Settings > Pet Adoption Limit","DefaultValue":"-1","Module":"MC Pregnancy"},{"SettingName":"Woohoo_RiskyWoohooPercents","Description":"Percentage chance that normal Woohoo will cause pregnancies (0-100) definable separately for Teens, Young Adults, Adults and Elders. If the percent is different for the ages of two Sims woohooing, then the percent for the target Sim (one that could become pregnant) will be used.","MenuPath":"MCCC > MC Woohoo > Woohoo Pregnancy > Risky Woohoo Percent","DefaultValue":"0% for All ages","Module":"MC Woohoo"},{"SettingName":"Pregnancy_BypassRenters","Description":"If enabled, when scheduled random pregnancies occur, bypass any Sim that lives in a rental unit for either a target, or a pregnancy partner.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Bypass Renters","DefaultValue":"True","Module":"MC Pregnancy"},{"SettingName":"Marriage_BypassRenters","Description":"If enabled, when scheduled random marriages occur (or when a pregnancy happens if the Auto Marriage Percentage is met), bypass any Sim that lives in a rental unit for either a target, or a pregnancy partner. Sims living in rental properties are treated differently, much like Ancestral Households. They cannot be moved-out. So, for example, if a target and a spouse both live in rental homes, they cannot get married because neither can move. Also, if one is in a rental and the other is ancestral, they cannot get married because neither can move. The marriage will always require that the non-renter can move in with the renter for the marriage to be successful.","MenuPath":"MCCC > MC Pregnancy > Marriage Sim Selection > Bypass Renters","DefaultValue":"True","Module":"MC Marriage"},{"SettingName":"Population_BypassAncestralMoveouts","Description":"When enabled, this will prevent single-Sim or elder Sim move-outs that can be enabled from MC Population from happening on Ancestral Households.","MenuPath":"MCCC > MC Population > Moving Settings > Bypass Ancestral Households","DefaultValue":"False","Module":"MC Population"},{"SettingName":"Relationship_BypassAncestral","Description":"If this is enabled, Sims will not leave an Ancestral Household either to move-in with another Sim or to move-out after a break-up.","MenuPath":"MCCC > MCCC Settings > Relationship Settings > Auto-Relationship Settings > Bypass Ancestral Households","DefaultValue":"False","Module":"MC Command Center"},{"SettingName":"Occult_IgnoreCasOnAbduction","Description":"If this is enabled, a Sim may become pregnant through alien abductions even if they're set in CAS Gender settings for 'Get Others Pregnant' or 'Neither' for pregnancy options (this also applies to the Flag for no Offspring and Flag to only get others pregnant). By default, Sims 4 does ignore the CAS Gender settings for abductions but MCCC does not. Enabling this setting makes MCCC work like the base game, but the default for MCCC is still to enforce those settings.","MenuPath":"MCCC > MC Occult > Abduction Pregnancy Settings > Ignore CAS Preferences","DefaultValue":"False","Module":"MC Occult"},{"SettingName":"Cleaner_MatchMedicalDevices","Description":"If a Sim has a medical device on one of their outfits, it will be copied to the other outfits (except for Swimwear, sleepwear and bathing) when the MC Cleaner item cleanup process runs. Note that the way Sims 4 handles these 'Medical Devices' is that they're earrings. They take the same slot as earrings do and you can't have a medical device and an earring at the same time. For this syncing to work, it has to check not only that a Sim has an 'earring' slot in-use on their outfit, but also that it is one of the medical device ID's that are included in the base game. I don't know if there are CC medical devices out there, or not, but if so, this syncing will not work for them. Also, earrings on existing outfits will be overridden by the hearing aids.","MenuPath":"MCCC > MC Cleaner > Item Cleaner > Sync Medical Devices","DefaultValue":"False","Module":"MC Cleaner"},{"SettingName":"Show_PregnancyAffairNotificationType","Description":"A notification post when a pregnancy from an affair will display depending on whether the target or partner Sim falls within the limits of this setting. These include: '0'-No pregnancy notifications, 'N'-NPC's only, 'P'-Played/Active Sims only, 'R'-Sims related to the Active Sims only, 'AF'-Sims that are friends of the Active Sims only, 'AR'-Sims that are romantically involved with the Active Sims only or 'AL'-All Sims not in the active household will show notifications.","MenuPath":"MCCC > Notification/Console/Menu Settings > Notification Settings > MC Pregnancy Notifications > Show Pregnancy Affair Notifications","DefaultValue":"'0'","Module":"MC Command Center"},{"SettingName":"Marriage_RequiredTraitsList","Description":"If a player creates a Required trait pair, then if either Sim has the first trait, then the other Sim must have the second trait for a marriage to happen. Just as an example, a Required Trait pair could be entered for 'Evil' and 'Dislikes Americana Music' (because that WOULD be evil!). If a Sim being checked for random marriage has the 'Evil' trait, then a spouse would have to have the 'Dislikes Americana Music' trait to be considered or vice versa. Required traits prevent Sims from being randomly married without matching the traits in the pair defined. Just some notes, as many of these can be entered as desired but nothing prevents a player from setting up traits that break the process altogether, so always be mindful of the trait pairs you're entering. Also, this of course ONLY applies to MCCC random marriages. Any marriages that happen elsewhere won't be affected by these settings.","MenuPath":"MCCC > MC Pregnancy > Spouse Sim Selection > Marriage Trait Limits > Required Traits","DefaultValue":"[] (an empty list)","Module":"MC Marriage"},{"SettingName":"Marriage_ConflictTraitsList","Description":"Conflicting Traits define a pair of traits that if either Sim have one of the Traits, then the other Sim must NOT have the other Trait to be valid for marriage. An easy example for this would be defining a Conflicting Trait Pair of 'Good' and 'Evil'. If one Sim has the 'Good' Trait, they will never marry a Sim with the 'Evil' trait. Just some notes, as many of these can be entered as desired but nothing prevents a player from setting up traits that break the process altogether, so always be mindful of the trait pairs you're entering. Also, this of course ONLY applies to MCCC random marriages. Any marriages that happen elsewhere won't be affected by these settings.","MenuPath":"MCCC > MC Pregnancy > Spouse Sim Selection > Marriage Trait Limits > Conflicting Traits","DefaultValue":"[] (an empty list)","Module":"MC Marriage"},{"SettingName":"Neighborhood_Action_Plan_Bypass","Description":"This feature allows choosing from any of the Neighborhood Action Plan policies for their neighborhood that they don't wish to have included. Note that, due to the way EA has set up Neighborhood Action Plans, the plans available to vote on are based on the Sim's neighborhood street, so a street is required to get the policy list. With that in mind, the active Sim must be a Sim living in a neighborhood when setting this setting or the option will not show-up in the menu and some policies may show-up or not based on the current neighborhood.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Neighborhood Action Plans Bypass","DefaultValue":"''","Module":"MC Command Center"},{"SettingName":"Woohoo_FriendlierWoohooPartner","Description":"If this is enabled, the Ask to be Woohoo Partner interaction may be used on any valid Sim, based on MC Woohoo settings, with a small amount of friendly relationship existing. In addition, any woohoo-type of interaction will fail much less often between Woohoo Partners.","MenuPath":"MCCC > MC Woohoo > Woohoo Actions > Allow Friendlier Woohoo Partners","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Cleaner_ItemCleaner","Description":"Cleaner Definitions provide the player with a way to set-up different types of CAS outfit parts that can be configured to automatically be removed from Sims when the scheduled cleaning processes run. There are detailed instructions on my website on the MC Cleaner page.","MenuPath":"MCCC > MC Cleaner > Item Cleaner","DefaultValue":"{}","Module":"MC Cleaner"},{"SettingName":"Dresser_CustomItemsOnly","Description":"When enabled, clothing items that are not custom are considered excluded always. Custom items are always considered to be included If a custom item isn't found in a reasonable sampling of random outfits from CAS, the item will be left as-is during cleaning (performance reasons). You can not use this setting and the 'Use Only Saved Outfit' setting. Also, if you have this setting enabled, you won't be able to add items to the include/exclude list as the include list is 'any custom item' and the exclude list is 'not a custom item'. This also causes outfit cleaning to take longer, so keep that in mind. It has to go through every outfit item and try to find a custom item randomly generating new outfits in CAS and testing them over and over. It tries a number of times and if it fails, it gives up, but that can take a while. If logging is enabled, you'll see a report in your log file of what outfit parts could not be replaced.","MenuPath":"MCCC > MC Dresser > Custom Items Only","DefaultValue":"false","Module":"MC Dresser"},{"SettingName":"Occult_OccultTypeAgeMultiplier","Description":"For an example of how this is currently used in the Sims 4, Mermaids have an extended Elder age span. They have a 335% multiplier so the elder age span is extended by that much longer, in additon to any other age span modifiers they might have. This setting adds the multiplier for any occult type, for any age span. 100% is the default for all occult types and age spans other than the before-mentioned Mermaid elder age span. Using an example, if I wanted aliens to have a longer adult age span, you would set the value to how much above 100% you want it to be increased, up to 500%. If I wanted Spellcasters to have a shorter elder lifespan, I would set the value to less than 100%, down to a minimum of 1%. 100% is default, greater than 100% makes it longer, less than 100% makes it shorter.","MenuPath":"MCCC > MC Occult > occult type > Aging Settings > Age Multiplier","DefaultValue":"Mermaids = 335% for Elder age, all other ages and all other occult types = 100%","Module":"MC Occult"},{"SettingName":"Occult_OccultTypeMaximumAge","Description":"This setting controls when Sims stop aging normally, if ever. It sets the age that this type of Sim will stop aging. The default for Vampires is 'Young Adults' and all other occult types have 'Normal' as their default maximum, which just means they age normally through all ages.","MenuPath":"MCCC > MC Occult > occult type > Aging Settings > Aging Maximum","DefaultValue":"Vampires = 'YA', all others = '0' for normal aging.","Module":"MC Occult"},{"SettingName":"AgeStopHuman","Description":"This setting allows specifying an age span that human (non-occult) Sims will stop aging when they are in that age-span. When this setting is used, a Sim will not be able to be normally aged-out of the age span. Birthday cakes and such will not have an option to age-up. Console cheats, Testing Cheats, MCCC's 'Set Age' command and that sort of manual age-up must be used.","MenuPath":"MCCC > MCCC Settings > Age Settings > Stop Human Aging","DefaultValue":"''","Module":"MC Command Center"},{"SettingName":"Marriage_FlagGenderPreferencePercent","Description":"This setting determines whether to make the Same Sex Percentage permanently mark Sims with the preference determined from a random cycle. If the random percentage check succeds for the setting percent, the Sim will be flagged as a 'Same Sex' only or 'Opposite Sex' only Sim going-forward so they will be treated as such for all future random marriage checks. Flags will have to be manually cleared for Sims that are set in a manner the player doesn't like. Or better yet, they can be cleared and set to the value the player does like and that will be used going forward.","MenuPath":"MCCC > MC Pregnancy > Marriage Sim Selection > Flag Gender Preference","DefaultValue":"0","Module":"MC Marriage"},{"SettingName":"Pregnancy_FlagGenderPreferencePercent","Description":"This setting determines whether to make the Same Sex Percentage permanently mark Sims with the preference determined from a random cycle. If the random percentage check succeds for the setting percent, the Sim will be flagged as a 'Same Sex' only or 'Opposite Sex' only Sim going-forward so they will be treated as such for all future random pregnancy checks. Flags will have to be manually cleared for Sims that are set in a manner the player doesn't like. Or better yet, they can be cleared and set to the value the player does like and that will be used going forward.","MenuPath":"MCCC > MC Pregnancy > Pregnant Sim Selection > Flag Gender Preference Percent","DefaultValue":"0","Module":"MC Pregnancy"},{"SettingName":"Woohoo_AllowGhostTFB","Description":"When enabled, this will allow ghost Sims to initiate try for baby with other Sims as well as be the target of Try for Baby.","MenuPath":"MCCC > MC Woohoo > Woohoo Actions > Allow Ghost Try for Baby","DefaultValue":"False","Module":"MC Woohoo"},{"SettingName":"Occult_CustomPregnancyFairyAlien","Description":"This setting defines the percent chance fairy and alien parents will have fairy, alien or hybrid babies per delivery. Defaults to 50 for fairy babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Fairies > Other Pregnancy > Custom Percentages > Fairy and Alien","DefaultValue":"0,0,-1,-1,-1,-1,50","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyFairyHuman","Description":"This setting defines the percent chance fairy and human parents will have fairy babies per delivery. Defaults to 50 for fairy. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Fairies > Other Pregnancy > Custom Percentages > Fairy and Human","DefaultValue":"-1,-1,-1,-1,-1,-1,50","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyFairyMermaid","Description":"This setting defines the percent chance fairy and mermaid parents will have fairy or mermaid babies per delivery. Defaults to 50 for fairy babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Fairies > Other Pregnancy > Custom Percentages > Fairy and Mermaid","DefaultValue":"-1,-1,-1,0,-1,-1,50","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyFairyVampire","Description":"This setting defines the percent chance fairy and vampire parents will have fairy or vampire babies per delivery. Defaults to 50 for fairy babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Faires > Other Pregnancy > Custom Percentages > Fairy and Vampire","DefaultValue":"-1,-1,0,-1,-1,-1,50","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyFairyWitch","Description":"This setting defines the percent chance fairy and spellcaster parents will have fairy or spellcaster babies per delivery. Defaults to 50 for fairy babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Fairies > Other Pregnancy > Custom Percentages > Fairy and Spellcaster","DefaultValue":"-1,-1,-1,-1,0,-1,50","Module":"MC Occult"},{"SettingName":"Occult_CustomPregnancyFairyWerewolf","Description":"This setting defines the percent chance fairy and werewolf parents will have fairy or werewolf babies per delivery. Defaults to 50 for fairy babies and zero for anything else. If no random roll matches any percentages defined in the settings, the baby will be human.","MenuPath":"MCCC > MC Occult > Fairies > Other Pregnancy > Custom Percentages > Fairy and Werewolf","DefaultValue":"-1,-1,-1,-1,-1,0,50","Module":"MC Occult"},{"SettingName":"Occult_MaximumWerewolves","Description":"Sets a maximum number of desired werewolves for the world. If the number of current werewolves in the world is greater than or equal to this number then no more werewolf babies will be BORN. This does not change homeless werewolves that the game generates, it only will prevent babies from being born as werewolves.","MenuPath":"MCCC > MC Occult > Werewolves > Maximum Werewolves","DefaultValue":"-1 = No limit","Module":"MC Occult"},{"SettingName":"Occult_MaximumFairies","Description":"Sets a maximum number of desired fairies for the world. If the number of current fairies in the world is greater than or equal to this number then no more fairy babies will be BORN. This does not change homeless fairies that the game generates, it only will prevent babies from being born as fairies.","MenuPath":"MCCC > MC Occult > Fairies > Maximum Fairies","DefaultValue":"-1 = No limit","Module":"MC Occult"},{"SettingName":"Marriage_RequireCASPregnancy","Description":"If enabled, when random marriages are checked, a spouse and partner will only be matched for marriage if one of the Sims is set in CAS to be able to impregnate other Sims and the other is flagged to become pregnant. Those CAS settings are ignored if this is disabled. Pregnancies will then only happen for this married couple if it's valid based on pregnancy settings (adoption for same sex Sims, for example).","MenuPath":"MCCC > MC Pregnancy > Other Marriage > Require CAS Pregnancy Match","DefaultValue":"True","Module":"MC Marriage"},{"SettingName":"Pregnancy_UseFrameForGender","Description":"When enabled, a Sim who has a Masculine Frame in CAS will be treated as a Male Sim and a Feminine Frame will be treated as a female Sim for all MC Pregnancy functions.","MenuPath":"MCCC > MC Pregnancy > Other Pregnancy > Use Physical Frame For Gender","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Marriage_UseFrameForGender","Description":"When enabled, a Sim who has a Masculine Frame in CAS will be treated as a Male Sim and a Feminine Frame will be treated as a female Sim for all MC Marriage functions.","MenuPath":"MCCC > MC Pregnancy > Other Marriage > Use Physical Frame For Gender","DefaultValue":"False","Module":"MC Marriage"},{"SettingName":"Pregnancy_PercentWeights","Description":"This was always hard-coded to EA's values previously (and calculated and hard-coded for offspring-count > 3). A player can now specify what the percentage chance for the offspring that they have selected for each child. If someone wants to have a lot of triplets, they can set the percentages to single: 5%, twins: 30%, triplets: 65% or whatever. Just an example, but it's up to the player now. It must add up to 100% across all offspring percents. Another note on this, EA has ALWAYS shared percents for birth percents between humans and pets. This is the same, in this case. They apply multipliers for pets to make them different, but the base percents are the same and shared. I've been thinking about the way they do this more and I think I may have a way, in the future, to break it up altogether so players using MCCC can completely split the percentages up into two settings but it's more work than I can dig-into right now. Another thing to keep in mind is that the highest offspring count between humans and pets is what will be used to determine pregnancy. If humans are set to 3 maximum offspring and pets are set to 5 maximum offspring, the offspring percents that the core game will use is 5. That can throw-off the percentages if the maximum offspring count is less on the current species being checked. If the maximum between both has the highest as 3 and the percentages are 75/20/5 but the current species has a maximum of 2, then it will use the percents 75/20/5 still to determine the two offspring born (75 and 20, basically. The 5 will be ignored). The default value is confusing to read, but should make more sense in the UI.","MenuPath":"MCCC > MC Pregnancy > Offspring > Offspring Percents","DefaultValue":"1 offspring = 100% chance for 1. 2 offspring = 90% chance for 1, 10% chance for 2. 3 offspring = 89% chance for 1, 10% chance for 2, 1% chance for 3. 4 offspring = 75% chance for 1, 15% chance for 2, 7% chance for 3, 3% chance for 4. 5 offspring = 55% chance for 1, 25% chance for 2, 13% chance for 3, 5% chance for 4, 2% chance for 5, 6 offspring = 35% chance for 1, 30% chance for 2, 18% chance for 3, 11% chance for 4, 4% chance for 5, 2% chance for 6.","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_OffspringGenderPercents","Description":"A percentage can be set for the chance a baby will be male and/or female. The default is male: 50% and female: 50%. The gender percentages must add up to 100%. Note that any time offspring settings like this are changed, it can affect current unborn babies for existing pregnancies. This isn't anything new. Just a warning!","MenuPath":"MCCC > MC Pregnancy > Offspring > Offspring Gender Percents","DefaultValue":"Male: 50%, Female: 50%","Module":"MC Pregnancy"},{"SettingName":"Pregnancy_UseAttractionValues","Description":"If this is enabled, MC Pregnancy will try to match a partner Sim to a candidate pregnant Sim using Sims with the highest attraction value before using a random Sim in the world. If one isn't found or if the Sim selected by attraction is not a valid partner for whatever reason, then the standard random Sim selection would be used. Note that depending on the size of the player's world, this setting can make processing take longer to determine matches for pregnancy so use with your discretion.","MenuPath":"MCCC > MC Pregnancy > Partner Sim Selection > Use Attraction Values","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Marriage_UseAttractionValues","Description":"If this is enabled, MC Marriage will try to match a spouse Sim to a candidate marriage Sim using Sims with the highest attraction value before using a random Sim in the world. If one isn't found or if the Sim selected by attraction is not a valid partner for whatever reason, then the standard random Sim selection would be used. Note that depending on the size of the player's world, this setting can make processing take longer to determine matches for marriage so use with your discretion.","MenuPath":"MCCC > MC Pregnancy > Spouse Sim Selection > Use Attraction Values","DefaultValue":"False","Module":"MC Marriage"},{"SettingName":"Cleaner_CleanupMultiRelations","Description":"Cleans any relationships in the world that have spouse Sims that are also related family members. Having both relationships will cause the family tree to lock-up when opened, so this removes the spouse relationship. Players can disable this, if they want, but it will cause problems with the family tree dialog as described.","MenuPath":"MCCC > MC Cleaner > Clean-up Multi-Relations","DefaultValue":"True","Module":"MC Cleaner"},{"SettingName":"Allow_NS_Deaths","Description":"If this setting is disabled, Sims will not die from Neighborhood Stories random deaths. Default is enabled so it allows EA Story Progression for random deaths.","MenuPath":"MCCC > Gameplay Settings > Death Settings > Allow NS Random Deaths","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Dresser_MakeupIncludesFacePaint","Description":"When this setting is enabled, the Remove Makeup command (MCCC > MC Dresser > Remove All Makeup) will also remove any facepaint the Sim may be wearing in addition to makeup. It will also make the 'Remove All Makeup' command appear on the MC Dresser menu if the Sim has facepaint only.","MenuPath":"MCCC > MC Dresser > Makeup Settings > Remove Makeup/Facepaint","DefaultValue":"False","Module":"MC Dresser"},{"SettingName":"Show_AutosaveNotifications","Description":"If this is disabled, when an autosave occurs, no notification message will be shown. Normally, a message is always shown so the player is aware of the save happening as well as the filename the autosave used. This setting can be used to disable that, if a player chooses that.","MenuPath":"MCCC > MCCC Settings > Notification / Console / Menu Settings > Notification Settings > Show Notifications > Show Autosave Notifications","DefaultValue":"True","Module":"MC Command Center"},{"SettingName":"Prestige_Difficulty_Adjustment","Description":"This setting Increases/decreases the speed of Dynasty Presige progression. Valid settings are from -50 to 10 with a default of zero. Negative is slower progress, positive is faster. Every negative point is -10%, so -10 is 100% slower, -20 is 200% slower, etc. Positive are 100% per point, so 2 is 200% faster up to 10 which is 1000% faster.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Dynasty Prestige Difficulty Adjustment","DefaultValue":"0","Module":"MC Command Center"},{"SettingName":"Decay_Ratio_Prestige","Description":"Allows changing the decay rate of the Prestige of a Sim in a Dynasty. 100, which is the default, results in normal prestige decay. Below 100 reduces the rate at which prestige decays. 50 = half the normal decay rate. 0 = no decay. etc. Going above 100 (up to 500) increases the rate at which prestige decays making it drop up-to 2x faster than default EA levels. Traits and buffs that affect Motive decay will still apply to the new decay rate as well unless it's set to zero.","MenuPath":"MCCC > MCCC Settings > Gameplay Settings > Motive Decay > Dynasty Prestige Decay Percent","DefaultValue":"100","Module":"MC Command Center"},{"SettingName":"Pregnancy_BypassBusinessOwnerMoveouts","Description":"Bypass Sim marriages and move-outs from MC Pregnancy. Since business owner Sims forget all their business information if they get moved, this setting is enabled by default to prevent that from happening.","MenuPath":"MCCC > MC Pregnancy > Other Pregnancy... > Bypass Business Owners","DefaultValue":"True","Module":"MC Pregnancy"},{"SettingName":"Population_BypassBusinessOwnerMoveouts","Description":"Bypass Sim move-outs from MC Population (Single Sim and Elder retirement move-outs) and Relationship Change behavior causing move-outs if the get_population_bypass_business_owner_moves setting is enabled and the Sim is a business owner. Since business owner Sims forget all their business information if they get moved, this setting is enabled by default to prevent that from happening.","MenuPath":"(MCCC > MC Population > Moving Settings > Bypass Business Owners","DefaultValue":"True","Module":"MC Population"},{"SettingName":"Pregnancy_ManualConfirmation","Description":"When enabled, every random pregnancy generated by MCCC will display a confirmation dialog for the player to choose to allow the pregnancy to continue or not. Note that this is ONLY pregnancies generated by the random pregnancy functionality in MCCC. It will not show confirmation dialogs from Neighborhood Stories or from manually starting pregnancies on Sims or things like that.","MenuPath":"MCCC > MC Pregnancy > Other Pregnancy... > Manual Confirmation","DefaultValue":"False","Module":"MC Pregnancy"},{"SettingName":"Marriage_BypassRobots","Description":"If this is enabled, then robots will not be either the target or the spouse for random marriages.","MenuPath":"MCCC > MC Pregnancy > Marriage Sim Selection > Bypass Robots","DefaultValue":"True","Module":"MC Marriage"},{"SettingName":"Marriage_ManualConfirmation","Description":"When enabled, every random marriage generated will display a confirmation dialog for the player to choose to allow the marriage to continue or not. Note that the marriage may still not happen if there are issues moving the Sims into the same household after confirmation.","MenuPath":"MCCC > MC Pregnancy > Other Marriage... > Manual Confirmation","DefaultValue":"False","Module":"MC Marriage"}]`);export{e as t};